(function(A){Object.assign(A.D,{"G5124":{"l":"οὗτος","o":1387,"ar":"<f><o>οὗτος</o>، <g>αὕτη, τοῦτο</g>، حالة الجر: <g>τούτου, ταύτης, τούτου</g>،</f> ضمير إشارة (علاقته بـ <g>ἐκεῖνος</g> كعلاقة <l>hic</l> بـ <l>ille</l>، أي «هذا» مقابل «ذاك»)، <s><b>هذا</b>؛ <s n=\"1.\">اسمًا: <b>هذا</b>، <b>هو</b>؛ <s n=\"(a)\">مطلقًا: <r v=\"Matt.3.17\"></r>، <r v=\"Mark.9.7\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"Luke.7.45\"></r>، <r v=\"John.1.15\"></r>، <r v=\"Acts.2.15\"></r>، وفي مواضع أخرى؛ للتعبير عن الاحتقار، <r v=\"Matt.13.55\"></r>، <r v=\"Matt.13.56\"></r>، <r v=\"Mark.6.2\"></r>، <r v=\"Mark.6.3\"></r>، <r v=\"John.6.42\"></r>، وفي مواضع أخرى؛ <g>εἰς τοῦτο</g> (لهذا)، <r v=\"Mark.1.38\"></r>، <r v=\"Rom.14.9\"></r>؛ <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>؛ انظر <r v=\"John.5.1\"></r>) (بعد هذا)، <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">إعاديًا (يشير إلى ما سبق): <r v=\"Matt.5.19\"></r>، <r v=\"Mark.3.35\"></r>، <r v=\"Luke.9.48\"></r>، <r v=\"John.6.46\"></r>، <r v=\"Rom.7.10\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">استباقيًا (يشير إلى ما يلي): يليه <g>ἵνα</g>، <r v=\"Luke.1.43\"></r>، <r v=\"John.3.19\"></r> (وكثيرًا) <r v=\"John.15.8\"></r>، <r v=\"Rom.14.9\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>، <r v=\"Luke.10.11\"></r>، <r v=\"John.9.30\"></r>، <r v=\"Acts.24.14\"></r>، <r v=\"Rom.2.3\"></r>، وفي مواضع أخرى؛ <g>ὅπως</g>، <r v=\"Rom.9.17\"></r>؛ <g>ἐάν</g>، <r v=\"John.13.35\"></r>؛</s> <s n=\"(d)\">تعابير خاصة: <g>τοῦτο μὲν . . . τ. δέ</g>: <b>من جهة . . . ومن جهة أخرى</b>، <r v=\"Heb.10.33\"></r>؛ <g>καὶ τοῦτο</g> (<g>τοῦτον</g>، <g>ταῦτα</g>): <b>وذلك</b> (<b>وإياه</b>) <b>أيضًا</b>، <r v=\"Rom.13.11\"></r>، <r v=\"1Cor.2.2\"></r>، <r v=\"Heb.11.12\"></r>؛ <g>τοῦτ’ ἐστιν</g>: <b>أي، أعني</b>، <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">صفةً مع اسم؛ <s n=\"(a)\">مع أداة التعريف، <s n=\"(α)\">قبل الأداة: <r v=\"Matt.12.32\"></r>، <r v=\"Mark.9.29\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"John.4.15\"></r>، <r v=\"Rom.11.24\"></r>، <r v=\"Rev.19.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(β)\">بعد الاسم: <r v=\"Matt.3.9\"></r>، <r v=\"Mark.12.16\"></r>، <r v=\"Luke.11.31\"></r>، <r v=\"John.4.13\"></r>، <r v=\"Acts.6.13\"></r>، <r v=\"Rom.15.28\"></r>، <r v=\"1Cor.1.20\"></r>، <r v=\"Rev.2.24\"></r>، وفي مواضع أخرى؛</s> </s> <s n=\"(b)\">مع اسم بدون أداة التعريف (بمعنى الخبر): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>، <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>، <r v=\"2Cor.13.1\"></r>.</s> </s> </s>","en":"<f><o>οὗτος</o>, <g>αὕτη, τοῦτο</g>, gen., <g>τούτου, ταύτης, τούτου</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2088\">זֶה</h>, <h n=\"H2063\">זֹאת</h>;]</e> </et> demonstr. pron. (related to <g>ἐκεῖνος</g> as <l>hic</l> to <l>ille</l>), <s><b>this</b>; <s n=\"1.\">as subst., <b>this one</b>, <b>he</b>; <s n=\"(a)\">absol.: <r v=\"Matt.3.17\"></r>, <r v=\"Mark.9.7\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"Luke.7.45\"></r>, <r v=\"John.1.15\"></r>, <r v=\"Acts.2.15\"></r>, al.; expressing contempt (cl.), <r v=\"Matt.13.55\"></r>, <r v=\"Matt.13.56\"></r>, <r v=\"Mark.6.2\"></r>, <r v=\"Mark.6.3\"></r>, <r v=\"John.6.42\"></r>, al.; <g>εἰς τοῦτο</g>, <r v=\"Mark.1.38\"></r>, <r v=\"Rom.14.9\"></r>; <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>; V. Westc. on <r v=\"John.5.1\"></r>), <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>, al.;</s> <s n=\"(b)\">epanaleptic (referring to what precedes): <r v=\"Matt.5.19\"></r>, <r v=\"Mark.3.35\"></r>, <r v=\"Luke.9.48\"></r>, <r v=\"John.6.46\"></r>, <r v=\"Rom.7.10\"></r>, al.;</s> <s n=\"(c)\">proleptic (referring to what follows): seq. <g>ἵνα</g> (Bl., § 69, 6), <r v=\"Luke.1.43\"></r>, <r v=\"John.3.19\"></r> (and freq.) <r v=\"John.15.8\"></r>, <r v=\"Rom.14.9\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Luke.10.11\"></r>, <r v=\"John.9.30\"></r>, <r v=\"Acts.24.14\"></r>, <r v=\"Rom.2.3\"></r>, al.; <g>ὅπως</g>, <r v=\"Rom.9.17\"></r>; <g>ἐάν</g>, <r v=\"John.13.35\"></r>;</s> <s n=\"(d)\">special idioms: <g>τοῦτο μὲν . . . τ. δέ</g> (cl), <b>partly . . . partly</b>, <r v=\"Heb.10.33\"></r>; <g>καὶ τοῦτο</g> (<g>τοῦτον</g>, <g>ταῦτα</g>), <b>and that</b> (<b>him</b>) <b>too</b>, <r v=\"Rom.13.11\"></r>, <r v=\"1Cor.2.2\"></r>, <r v=\"Heb.11.12\"></r>; <g>τοῦτ’ ἐστιν</g>, <b>that is to say</b>, <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">As adj., c. subst.; <s n=\"(a)\">c. art. <s n=\"(α)\">before the art.: <r v=\"Matt.12.32\"></r>, <r v=\"Mark.9.29\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"John.4.15\"></r>, <r v=\"Rom.11.24\"></r>, <r v=\"Rev.19.9\"></r>, al.;</s> <s n=\"(β)\">after the noun: <r v=\"Matt.3.9\"></r>, <r v=\"Mark.12.16\"></r>, <r v=\"Luke.11.31\"></r>, <r v=\"John.4.13\"></r>, <r v=\"Acts.6.13\"></r>, <r v=\"Rom.15.28\"></r>, <r v=\"1Cor.1.20\"></r>, <r v=\"Rev.2.24\"></r>, al.;</s> </s> <s n=\"(b)\">c. subst. anarth. (with predicative force; Bl., § 49, 4): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>, <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>, <r v=\"2Cor.13.1\"></r>.</s> </s> </s>"},"G5100":{"l":"τις","o":496,"ar":"<f><o>τις</o>، المحايد <g>τι</g>، حالة الجر <g>τινός</g>، </f> ضمير نكرة ملحق، علاقته بالاستفهامي <g>τίς</g> كعلاقة <g>πού, πως, ποτέ</g> بـ <g>ποῦ, πῶς, πότε</g>. <s> <s n=\"I.\">اسمًا، <s n=\"1.\"><b>واحد، أحدٌ ما، شخص معيَّن</b>: <r v=\"Luke.9.49\"></r>، <r v=\"John.11.1\"></r>، <r v=\"Acts.5.25\"></r>، وفي مواضع أخرى؛ جمع، <g>τίνες</g>: <b>قومٌ، بعضٌ</b>: <r v=\"Luke.13.1\"></r>، <r v=\"Acts.15.1\"></r>، <r v=\"Rom.3.8\"></r>، وفي مواضع أخرى. </s> <s n=\"2.\"><b>أحدٌ، أيُّ أحد، شيءٌ، أيُّ شيء</b>: <r v=\"Matt.12.29\"></r>، <r v=\"Mark.9.30\"></r>، <r v=\"Luke.8.46\"></r>، <r v=\"John.2.25\"></r>، <r v=\"Acts.17.25\"></r>، <r v=\"Rom.5.7\"></r>، وفي مواضع أخرى؛ بمعنى النكرة العامة: <b>المرء</b>، <r v=\"Mark.8.4\"></r>، <r v=\"John.2.25\"></r>، <r v=\"Rom.8.24\"></r>، وفي مواضع أخرى؛ جمع، <g>τινες</g>: <b>بعضٌ، قومٌ</b>، <r v=\"Mark.14.4\"></r>، وفي مواضع أخرى. </s> </s> <s n=\"II.\">صفةً، <s n=\"1.\"><b>ما، معيَّن</b> (إنسانٌ ما): <r v=\"Matt.18.12\"></r>، <r v=\"Luke.1.5\"></r> <r v=\"Luke.8.27\"></r>، <r v=\"Acts.3.2\"></r>، وفي مواضع أخرى؛ مع أسماء العَلَم، <r v=\"Mark.15.21\"></r>، <r v=\"Luke.23.26\"></r>، وفي مواضع أخرى؛ مع المضاف إليه التبعيضي، <r v=\"Luke.7.19\"></r>، وفي مواضع أخرى. </s> <s n=\"2.\"><b>بعض، شيء من</b>: <r v=\"Mark.16.18\"></r>، <r v=\"John.5.14\"></r>، <r v=\"Acts.17.21\"></r> <r v=\"Acts.24.24\"></r>، <r v=\"Heb.11.40\"></r>، وفي مواضع أخرى. </s> </s> </s>","en":"<f><o>τις</o>, neut., <g>τι</g>, gen., <g>τινός</g>, </f> enclitic indefinite pron., related to interrog. <g>τίς</g> as <g>πού, πως, ποτέ</g> to <g>ποῦ, πῶς, πότε</g>. <s> <s n=\"I.\">As subst., <s n=\"1.\"><b>one, a certain one</b>: <r v=\"Luke.9.49\"></r>, <r v=\"John.11.1\"></r>, <r v=\"Acts.5.25\"></r>, al.; pl., <g>τίνες</g>, <b>certain, some</b>: <r v=\"Luke.13.1\"></r>, <r v=\"Acts.15.1\"></r>, <r v=\"Rom.3.8\"></r>, al. </s> <s n=\"2.\"><b>someone, anyone, something, anything</b>: <r v=\"Matt.12.29\"></r>, <r v=\"Mark.9.30\"></r>, <r v=\"Luke.8.46\"></r>, <r v=\"John.2.25\"></r>, <r v=\"Acts.17.25\"></r>, <r v=\"Rom.5.7\"></r>, al.; = indef., <b>one</b> (French <i>on</i>), <r v=\"Mark.8.4\"></r>, <r v=\"John.2.25\"></r>, <r v=\"Rom.8.24\"></r>, al.; pl., <g>τινες</g>, <b>some</b>, <r v=\"Mark.14.4\"></r>, al. </s> </s> <s n=\"II.\">As adj., <s n=\"1.\"><b>a certain</b>: <r v=\"Matt.18.12\"></r>, <r v=\"Luke.1.5\"></r> <r v=\"Luke.8.27\"></r>, <r v=\"Acts.3.2\"></r>, al.; with proper names, <r v=\"Mark.15.21\"></r>, <r v=\"Luke.23.26\"></r>, al.; c. gen. partit., <r v=\"Luke.7.19\"></r>, al. </s> <s n=\"2.\"><b>some</b>: <r v=\"Mark.16.18\"></r>, <r v=\"John.5.14\"></r>, <r v=\"Acts.17.21\"></r> <r v=\"Acts.24.24\"></r>, <r v=\"Heb.11.40\"></r>, al. </s> </s> </s>"},"G5108":{"l":"τοιοῦτος","o":57,"ar":"<f><o>τοιοῦτος</o>، <g>-αύτη, -οῦτο</g></f> <s>مقابِلُ <g>οἷος, ὁποῖος, ὥς</g> إلخ، </s> <s><b>مثل هذا، من هذا النوع، كهذا</b>: <r v=\"Matt.9.8\"></r> <r v=\"Matt.18.5\"></r>، <r v=\"Mark.4.33\"></r> <r v=\"Mark.6.2\"></r> <r v=\"Mark.7.13\"></r> <r v=\"Mark.9.37\"></r>، <r v=\"John.9.16\"></r>، <r v=\"Acts.16.24\"></r>، <r v=\"1Cor.5.1\"></r> <r v=\"1Cor.11.16\"></r>، <r v=\"2Cor.3.4\"></r>، <r v=\"2Cor.3.12\"></r> <r v=\"2Cor.12.3\"></r>، <r v=\"Heb.7.26\"></r> <r v=\"Heb.8.1\"></r> <r v=\"Heb.12.3\"></r> <r v=\"Heb.13.16\"></r>، <r v=\"Jas.4.16\"></r>؛ <g>οἷος . . . τ.</g> (كما ... هكذا)، <r v=\"1Cor.15.48\"></r>، <r v=\"2Cor.10.11\"></r>؛ والتعبير نفسه على سبيل الحشو، <r v=\"Mark.13.19\"></r>؛ يليه <g>ὁποῖος</g>، <r v=\"Acts.26.29\"></r>؛ <g>ὥς</g>، <r v=\"Phlm.1.9\"></r>. اسمًا، بدون أداة التعريف: جمع، <r v=\"Luke.9.9\"></r>؛ ومع أداة التعريف، <g>ὁ τ.</g>: <b>مثل هذا (الشخص)</b>، (قارن <r v=\"Gal.5.21\"></r>): <r v=\"Acts.22.22\"></r>، <r v=\"1Cor.5.5\"></r>، وفي مواضع أخرى؛ جمع، <r v=\"Matt.19.14\"></r>، <r v=\"Mark.10.14\"></r>، وفي مواضع أخرى؛ المحايد الجمع، <r v=\"Acts.19.25\"></r>، <r v=\"Rom.1.32\"></r>، وفي مواضع أخرى.</s>","en":"<f><o>τοιοῦτος</o>, <g>-αύτη, -οῦτο</g></f> <et> <e t=\"derivation\">(as usually in Att.. prose. Ep. and Ion. neut. <g>-οῦτον</g> in Al., <r v=\"Acts.21.25\"></r>, Rec. only), </e> </et> <s>correlat. of <g>οἷος, ὁποῖος, ὥς</g>, etc., </s> <s><b>such as this, of such a kind, such</b>: <r v=\"Matt.9.8\"></r> <r v=\"Matt.18.5\"></r>, <r v=\"Mark.4.33\"></r> <r v=\"Mark.6.2\"></r> <r v=\"Mark.7.13\"></r> <r v=\"Mark.9.37\"></r> (T, <g>τούτων</g>), <r v=\"John.9.16\"></r>, <r v=\"Acts.16.24\"></r>, <r v=\"1Cor.5.1\"></r> <r v=\"1Cor.11.16\"></r>, <r v=\"2Cor.3.4\"></r>, <r v=\"2Cor.3.12\"></r> <r v=\"2Cor.12.3\"></r>, <r v=\"Heb.7.26\"></r> <r v=\"Heb.8.1\"></r> <r v=\"Heb.12.3\"></r> <r v=\"Heb.13.16\"></r>, <r v=\"Jas.4.16\"></r>; <g>οἷος . . . τ.</g>, <r v=\"1Cor.15.48\"></r>, <r v=\"2Cor.10.11\"></r>; id. pleonast. (v. Bl., § 50, 4), <r v=\"Mark.13.19\"></r>; seq. <g>ὁποῖος</g>, <r v=\"Acts.26.29\"></r>; <g>ὥς</g>, <r v=\"Phlm.1.9\"></r>. As subst., anarth: pl., <r v=\"Luke.9.9\"></r>; c. art., <g>ὁ τ.</g>, <b>such a one</b> (Bl., § 47, 9; Ellic. on <r v=\"Gal.5.21\"></r>): <r v=\"Acts.22.22\"></r>, <r v=\"1Cor.5.5\"></r>, al.; pl., <r v=\"Matt.19.14\"></r>, <r v=\"Mark.10.14\"></r>, al.; neut. pl., <r v=\"Acts.19.25\"></r>, <r v=\"Rom.1.32\"></r>, al.</s>"},"G5190":{"l":"Τύχικος","o":5,"ar":"<f><o>Τύχικος</o>، <g>-ου, ὁ</g></f> <s><b>تيخيكس</b>: <r v=\"Acts.20.4\"></r>، <r v=\"Eph.6.21\"></r>، <r v=\"Col.4.7\"></r>، <r v=\"2Tim.4.12\"></r>، <r v=\"Titus.3.12\"></r>.†</s>","en":"<f><o>Τύχικος</o>, (T, Rec., <g>Τυχικός</g>), <g>-ου, ὁ</g></f> <s><b>Tychicus</b>: <r v=\"Acts.20.4\"></r>, <r v=\"Eph.6.21\"></r>, <r v=\"Col.4.7\"></r>, <r v=\"2Tim.4.12\"></r>, <r v=\"Titus.3.12\"></r>.†</s>"},"G5117":{"l":"τόπος","o":109,"ar":"<f><o>τόπος</o>، <g>-ου, ὁ</g>، </f> <s><b>مكان (موضع)</b>: <r v=\"Luke.4.37\"></r> <r v=\"Luke.10.1\"></r>، <r v=\"Luke.10.32\"></r>، <r v=\"John.5.13\"></r> <r v=\"John.6.10\"></r>، <r v=\"Acts.12.17\"></r>، <r v=\"1Cor.1.2\"></r>، وفي مواضع أخرى؛ <g>τ. ἅγιος</g> (قارن <r v=\"Isa.60.13\"></r>)، <r v=\"Matt.24.15\"></r>؛ <g>ἔρημος</g>، <r v=\"Matt.14.13\"></r>، وفي مواضع أخرى؛ <g>πεδινός</g>، <r v=\"Luke.6.17\"></r>؛ <g>ἄνυδρος</g> (الجمع)، <r v=\"Matt.12.43\"></r>، <r v=\"Luke.11.24\"></r>؛ <g>κατὰ τόπους</g> (الترجمات الإنجليزية: <b>في أماكن</b>)، <r v=\"Matt.24.7\"></r>، <r v=\"Mark.13.8\"></r>؛ <g>τραχεῖς τ.</g>، <r v=\"Acts.27.29\"></r>؛ <g>τ. διθάλασσος</g> (انظره)، <r v=\"Acts.27.41\"></r>؛ <g>ἑτοιμάζειν τ.</g>، <r v=\"John.14.2\"></r>، <r v=\"John.14.3\"></r>؛ <g>ἔχειν</g>، <r v=\"Rev.12.6\"></r>؛ <g>διδόναι</g>، <r v=\"Luke.14.9\"></r>؛ مع المضاف إليه للتعريف، <g>τ. βασάνου</g>، <r v=\"Luke.16.28\"></r>؛ <g>τ. καταπαύσεως</g>، <r v=\"Acts.7.49\"></r>؛ <g>κρανίου</g>، <r v=\"Matt.27.33\"></r>، <r v=\"Mark.15.22\"></r>، <r v=\"John.19.17\"></r>؛ يليه <g>οὗ</g>، <r v=\"Rom.9.26\"></r>؛ <g>ὅπου</g>، <r v=\"Matt.28.6\"></r>، <r v=\"Mark.16.6\"></r>، <r v=\"John.4.20\"></r> <r v=\"John.6.23\"></r> <r v=\"John.10.40\"></r> <r v=\"John.11.30\"></r> <r v=\"John.19.41\"></r>؛ <g>ἐν ᾧ</g>، <r v=\"John.11.6\"></r>؛ <g>ἐφ’ ᾧ</g>، <r v=\"Acts.7.33\"></r>؛ عن المكان الذي يشغله شخص أو شيء، <r v=\"Rev.2.5\"></r> <r v=\"Rev.6.14\"></r> <r v=\"Rev.12.8\"></r>؛ <g>τ. μαχαίρας</g>، <r v=\"Matt.26.52\"></r>؛ <g>ὁ ἴδιος τ.</g>، <r v=\"Acts.1.25\"></r>؛ عن موضع في كتاب، <r v=\"Luke.4.17\"></r>. مجازيًا، عن الحال أو المنزلة أو المناسبة أو الفرصة أو المقدرة: <r v=\"Acts.25.16\"></r>، <r v=\"Rom.12.19\"></r> <r v=\"Rom.15.23\"></r>، <r v=\"Eph.4.27\"></r> (قارن <r v=\"Sir.38.12\"></r>). </s>","en":"<f><o>τόπος</o>, <g>-ου, ὁ</g>, </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4725\">מָקֹום</h> ;]</e> </et> <s><b>place</b>: <r v=\"Luke.4.37\"></r> <r v=\"Luke.10.1\"></r>, <r v=\"Luke.10.32\"></r>, <r v=\"John.5.13\"></r> <r v=\"John.6.10\"></r>, <r v=\"Acts.12.17\"></r>, <r v=\"1Cor.1.2\"></r>, al.; <g>τ. ἅγιος</g> (cf. <r v=\"Isa.60.13\"></r>), <r v=\"Matt.24.15\"></r>; <g>ἔρημος</g>, <r v=\"Matt.14.13\"></r>, al.; <g>πεδινός</g>, <r v=\"Luke.6.17\"></r>; <g>ἄνυδρος</g> (pl.), <r v=\"Matt.12.43\"></r>, <r v=\"Luke.11.24\"></r>; <g>κατὰ τόπους</g> (EV, <b>in divers places</b>), <r v=\"Matt.24.7\"></r>, <r v=\"Mark.13.8\"></r>; <g>τραχεῖς τ.</g>, <r v=\"Acts.27.29\"></r>; <g>τ. διθάλασσος</g> (q.v.), <r v=\"Acts.27.41\"></r>; <g>ἑτοιμάζειν τ.</g>, <r v=\"John.14.2\"></r>, <r v=\"John.14.3\"></r>; <g>ἔχειν</g>, <r v=\"Rev.12.6\"></r>; <g>διδόναι</g>, <r v=\"Luke.14.9\"></r>; c. gen. defin., <g>τ. βασάνου</g>, <r v=\"Luke.16.28\"></r>; <g>τ. καταπαύσεως</g>, <r v=\"Acts.7.49\"></r>; <g>κρανίου</g>, <r v=\"Matt.27.33\"></r>, <r v=\"Mark.15.22\"></r>, <r v=\"John.19.17\"></r>; seq. <g>οὗ</g>, <r v=\"Rom.9.26\"></r>; <g>ὅπου</g>, <r v=\"Matt.28.6\"></r>, <r v=\"Mark.16.6\"></r>, <r v=\"John.4.20\"></r> <r v=\"John.6.23\"></r> <r v=\"John.10.40\"></r> <r v=\"John.11.30\"></r> <r v=\"John.19.41\"></r>; <g>ἐν ᾧ</g>, <r v=\"John.11.6\"></r>; <g>ἐφ’ ᾧ</g>, <r v=\"Acts.7.33\"></r>; of a place which a person or thing occupies, <r v=\"Rev.2.5\"></r> <r v=\"Rev.6.14\"></r> <r v=\"Rev.12.8\"></r>; <g>τ. μαχαίρας</g>, <r v=\"Matt.26.52\"></r>; <g>ὁ ἴδιος τ.</g>, <r v=\"Acts.1.25\"></r>; of a place in a book, <r v=\"Luke.4.17\"></r> (cf. Clem. Rom., <i>I Co.</i>, 8, 4). Metaph., of condition, station, occasion, opportunity or power: <r v=\"Acts.25.16\"></r>, <r v=\"Rom.12.19\"></r> <r v=\"Rom.15.23\"></r>, <r v=\"Eph.4.27\"></r> (cf. <r v=\"Sir.38.12\"></r>). </s> <sy><i>SYN.</i>: <g>χώρα</g> (extensive), <b>region</b>; <g>χωρίον</g> (enclosed), <b>a piece of ground</b>. <g>τ.</g> is \"a portion of space viewed in reference to its occupancy, or as appropriated to a thing \" (Grimm-Thayer, s.v.).</sy>"},"G5156":{"l":"τρόμος","o":5,"ar":"<f><o>τρόμος</o>، <g>-ου, ὁ</g></f> <s><b>رِعدة، ارتعاد</b>، خاصةً من الخوف: <r v=\"Mark.16.8\"></r>؛ <g>φόβος κ. τ.</g> (كما في <r v=\"Gen.9.2\"></r>، <r v=\"Exod.15.16\"></r>، <r v=\"Deut.2.25\"></r>، <r v=\"Isa.19.16\"></r>، وفي مواضع أخرى)، <r v=\"1Cor.2.3\"></r>، <r v=\"2Cor.7.15\"></r>، <r v=\"Eph.6.5\"></r>، <r v=\"Phil.2.12\"></r>.†</s>","en":"<f><o>τρόμος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>τρέμω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H7461\">רִעָדָה</h>, <h n=\"H7461\">רַעַד</h>, <h n=\"H6343\">פַּחַד</h>, etc. ;]</e> </et> <s><b>trembling, quaking</b>, esp. from fear: <r v=\"Mark.16.8\"></r>; <g>φόβος κ. τ.</g> (as in <r v=\"Gen.9.2\"></r>, <r v=\"Exod.15.16\"></r>, <r v=\"Deut.2.25\"></r>, <r v=\"Isa.19.16\"></r>, al.), <r v=\"1Cor.2.3\"></r>, <r v=\"2Cor.7.15\"></r>, <r v=\"Eph.6.5\"></r>, <r v=\"Phil.2.12\"></r>.†</s>"},"G5127":{"l":"οὗτος","o":1387,"ar":"<f><o>οὗτος</o>، <g>αὕτη, τοῦτο</g>، حالة الجر: <g>τούτου, ταύτης, τούτου</g>،</f> ضمير إشارة (علاقته بـ <g>ἐκεῖνος</g> كعلاقة <l>hic</l> بـ <l>ille</l>)، <s><b>هذا</b>؛ <s n=\"1.\">بمعنى الاسم: <b>هذا الشخص</b>، <b>هو</b>؛ <s n=\"(a)\">مطلقًا (بلا مفعول): <r v=\"Matt.3.17\"></r>، <r v=\"Mark.9.7\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"Luke.7.45\"></r>، <r v=\"John.1.15\"></r>، <r v=\"Acts.2.15\"></r>، وفي مواضع أخرى؛ للتعبير عن الازدراء، <r v=\"Matt.13.55\"></r>، <r v=\"Matt.13.56\"></r>، <r v=\"Mark.6.2\"></r>، <r v=\"Mark.6.3\"></r>، <r v=\"John.6.42\"></r>، وفي مواضع أخرى؛ <g>εἰς τοῦτο</g>، <r v=\"Mark.1.38\"></r>، <r v=\"Rom.14.9\"></r>؛ <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>؛ قارن <r v=\"John.5.1\"></r>)، <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">استئنافي (يشير إلى ما سبق): <r v=\"Matt.5.19\"></r>، <r v=\"Mark.3.35\"></r>، <r v=\"Luke.9.48\"></r>، <r v=\"John.6.46\"></r>، <r v=\"Rom.7.10\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">استباقي (يشير إلى ما يلي): يليه <g>ἵνα</g>، <r v=\"Luke.1.43\"></r>، <r v=\"John.3.19\"></r> (وكثيرًا) <r v=\"John.15.8\"></r>، <r v=\"Rom.14.9\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>، <r v=\"Luke.10.11\"></r>، <r v=\"John.9.30\"></r>، <r v=\"Acts.24.14\"></r>، <r v=\"Rom.2.3\"></r>، وفي مواضع أخرى؛ <g>ὅπως</g>، <r v=\"Rom.9.17\"></r>؛ <g>ἐάν</g>، <r v=\"John.13.35\"></r>؛</s> <s n=\"(d)\">تعابير خاصة: <g>τοῦτο μὲν . . . τ. δέ</g>، <b>من جهة . . . ومن جهة أخرى</b>، <r v=\"Heb.10.33\"></r>؛ <g>καὶ τοῦτο</g> (<g>τοῦτον</g>، <g>ταῦτα</g>)، <b>وذلك</b> (<b>وإياه</b>) <b>أيضًا</b>، <r v=\"Rom.13.11\"></r>، <r v=\"1Cor.2.2\"></r>، <r v=\"Heb.11.12\"></r>؛ <g>τοῦτ’ ἐστιν</g>، <b>أي</b> (<b>بمعنى</b>)، <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">صفةً، مع اسم؛ <s n=\"(a)\">مع أداة التعريف <s n=\"(α)\">قبل أداة التعريف: <r v=\"Matt.12.32\"></r>، <r v=\"Mark.9.29\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"John.4.15\"></r>، <r v=\"Rom.11.24\"></r>، <r v=\"Rev.19.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(β)\">بعد الاسم: <r v=\"Matt.3.9\"></r>، <r v=\"Mark.12.16\"></r>، <r v=\"Luke.11.31\"></r>، <r v=\"John.4.13\"></r>، <r v=\"Acts.6.13\"></r>، <r v=\"Rom.15.28\"></r>، <r v=\"1Cor.1.20\"></r>، <r v=\"Rev.2.24\"></r>، وفي مواضع أخرى؛</s> </s> <s n=\"(b)\">مع اسم بدون أداة التعريف (بقوة الخبر): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>، <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>، <r v=\"2Cor.13.1\"></r>.</s> </s> </s>","en":"<f><o>οὗτος</o>, <g>αὕτη, τοῦτο</g>, gen., <g>τούτου, ταύτης, τούτου</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2088\">זֶה</h>, <h n=\"H2063\">זֹאת</h>;]</e> </et> demonstr. pron. (related to <g>ἐκεῖνος</g> as <l>hic</l> to <l>ille</l>), <s><b>this</b>; <s n=\"1.\">as subst., <b>this one</b>, <b>he</b>; <s n=\"(a)\">absol.: <r v=\"Matt.3.17\"></r>, <r v=\"Mark.9.7\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"Luke.7.45\"></r>, <r v=\"John.1.15\"></r>, <r v=\"Acts.2.15\"></r>, al.; expressing contempt (cl.), <r v=\"Matt.13.55\"></r>, <r v=\"Matt.13.56\"></r>, <r v=\"Mark.6.2\"></r>, <r v=\"Mark.6.3\"></r>, <r v=\"John.6.42\"></r>, al.; <g>εἰς τοῦτο</g>, <r v=\"Mark.1.38\"></r>, <r v=\"Rom.14.9\"></r>; <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>; V. Westc. on <r v=\"John.5.1\"></r>), <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>, al.;</s> <s n=\"(b)\">epanaleptic (referring to what precedes): <r v=\"Matt.5.19\"></r>, <r v=\"Mark.3.35\"></r>, <r v=\"Luke.9.48\"></r>, <r v=\"John.6.46\"></r>, <r v=\"Rom.7.10\"></r>, al.;</s> <s n=\"(c)\">proleptic (referring to what follows): seq. <g>ἵνα</g> (Bl., § 69, 6), <r v=\"Luke.1.43\"></r>, <r v=\"John.3.19\"></r> (and freq.) <r v=\"John.15.8\"></r>, <r v=\"Rom.14.9\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Luke.10.11\"></r>, <r v=\"John.9.30\"></r>, <r v=\"Acts.24.14\"></r>, <r v=\"Rom.2.3\"></r>, al.; <g>ὅπως</g>, <r v=\"Rom.9.17\"></r>; <g>ἐάν</g>, <r v=\"John.13.35\"></r>;</s> <s n=\"(d)\">special idioms: <g>τοῦτο μὲν . . . τ. δέ</g> (cl), <b>partly . . . partly</b>, <r v=\"Heb.10.33\"></r>; <g>καὶ τοῦτο</g> (<g>τοῦτον</g>, <g>ταῦτα</g>), <b>and that</b> (<b>him</b>) <b>too</b>, <r v=\"Rom.13.11\"></r>, <r v=\"1Cor.2.2\"></r>, <r v=\"Heb.11.12\"></r>; <g>τοῦτ’ ἐστιν</g>, <b>that is to say</b>, <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">As adj., c. subst.; <s n=\"(a)\">c. art. <s n=\"(α)\">before the art.: <r v=\"Matt.12.32\"></r>, <r v=\"Mark.9.29\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"John.4.15\"></r>, <r v=\"Rom.11.24\"></r>, <r v=\"Rev.19.9\"></r>, al.;</s> <s n=\"(β)\">after the noun: <r v=\"Matt.3.9\"></r>, <r v=\"Mark.12.16\"></r>, <r v=\"Luke.11.31\"></r>, <r v=\"John.4.13\"></r>, <r v=\"Acts.6.13\"></r>, <r v=\"Rom.15.28\"></r>, <r v=\"1Cor.1.20\"></r>, <r v=\"Rev.2.24\"></r>, al.;</s> </s> <s n=\"(b)\">c. subst. anarth. (with predicative force; Bl., § 49, 4): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>, <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>, <r v=\"2Cor.13.1\"></r>.</s> </s> </s>"},"G5154":{"l":"τρίτος","o":55,"ar":"<f><o>τρίτος</o>، <g>-η, -ον </g></f> <s><b>الثالث</b>: <r v=\"Matt.22.26\"></r>، <r v=\"Mark.12.21\"></r> <r v=\"Mark.15.25\"></r>، <r v=\"Luke.24.21\"></r>، <r v=\"Acts.2.15\"></r>، وفي مواضع أخرى؛ <g>τῇ τ. ἡμέρᾳ</g> (أي <b>بعد غدٍ</b>)، <r v=\"Matt.16.21\"></r>، <r v=\"Luke.24.46\"></r>، وفي مواضع أخرى؛ بمعنى الاسم، المنصوب المذكر، <g>τρίτον</g>، <b>ثالثًا</b> (أي عبدًا ثالثًا)، <r v=\"Luke.20.12\"></r>؛ المحايد، <g>τὸ τ.</g>، مع المضاف إليه، <b>الثلث من</b>: <r v=\"Rev.8.7-Rev.8.12\"></r> <r v=\"Rev.9.15\"></r>، <r v=\"Rev.9.18\"></r> <r v=\"Rev.12.4\"></r>. ظرفًا، <g>τὸ τ.</g>، <b>المرة الثالثة</b>: <r v=\"Mark.14.41\"></r>، <r v=\"John.21.17\"></r>؛ بدون أداة التعريف، <g>τρίτον</g>، مرة ثالثة، <r v=\"Luke.23.22\"></r>، <r v=\"John.21.14\"></r>، <r v=\"2Cor.12.14\"></r> <r v=\"2Cor.13.1\"></r>؛ في التعداد، <b>ثالثًا</b>، <r v=\"1Cor.12.28\"></r>؛ <g>ἐκ τ.</g>، <b>مرة ثالثة</b>، <r v=\"Matt.26.44\"></r> </s>","en":"<f><o>τρίτος</o>, <g>-η, -ον </g></f> <s><b>the third</b>: <r v=\"Matt.22.26\"></r>, <r v=\"Mark.12.21\"></r> <r v=\"Mark.15.25\"></r>, <r v=\"Luke.24.21\"></r>, <r v=\"Acts.2.15\"></r>, al.; <g>τῇ τ. ἡμέρᾳ</g> (i.e. <b>the next day but one</b>: Xen., al.; v. Field, <i>Notes</i>, 11 ff.), <r v=\"Matt.16.21\"></r>, <r v=\"Luke.24.46\"></r>, al.; substantively, acc. masc., <g>τρίτον</g>, <b>a third</b> (servant), <r v=\"Luke.20.12\"></r>; neut., <g>τὸ τ.</g>, c. gen., <b>the third part of</b>: <r v=\"Rev.8.7-Rev.8.12\"></r> <r v=\"Rev.9.15\"></r>, <r v=\"Rev.9.18\"></r> <r v=\"Rev.12.4\"></r>. As adv., <g>τὸ τ.</g>, <b>the third time</b>: <r v=\"Mark.14.41\"></r>, <r v=\"John.21.17\"></r>; anarth., <g>τρίτον</g>, a third time, <r v=\"Luke.23.22\"></r>, <r v=\"John.21.14\"></r>, <r v=\"2Cor.12.14\"></r> <r v=\"2Cor.13.1\"></r>; in enumerations, <b>thirdly</b>, <r v=\"1Cor.12.28\"></r>; <g>ἐκ τ.</g>, <b>a third time</b>, <r v=\"Matt.26.44\"></r> </s>"},"G5170":{"l":"Τρύφαινα","o":1,"ar":"<f><o>Τρύφαινα</o>، <g>-ης, ἡ </g></f> <s><b>تريفينا</b>: <r v=\"Rom.16.12\"></r>.†</s>","en":"<f><o>Τρύφαινα</o>, <g>-ης, ἡ </g></f> <s><b>Tryphæna</b>: <r v=\"Rom.16.12\"></r> (v. Lft., <i>Phl.</i>, 175 f.; MM, xxv).†</s>"},"G5144":{"l":"τριάκοντα","o":11,"ar":"<f><o>τριάκοντα</o>، <g>ἱο, αἱ, τά</g> لا يُصرَّف </f> <s><b>ثلاثون</b>: <r v=\"Matt.13.8\"></r>، وفي مواضع أخرى. </s>","en":"<f><o>τριάκοντα</o>, <g>ἱο, αἱ, τά</g> indecl. </f> <et> <e t=\"derivation\">(&lt; <g>τρεῖς</g>), </e> </et> <s><b>thirty</b>: <r v=\"Matt.13.8\"></r>, al. </s>"},"G5101":{"l":"τίς","o":566,"ar":"<f><o>τίς</o>، المحايد <g>τί</g>، حالة الجر <g>τίνος</g>، ضمير استفهام، [في السبعينية ترجمةً لـ <h n=\"H4100,H4310\">מָה ,מִי</h>؛] في المذكر والمؤنث: </f> <s><b>مَن، أيّ، ما؟</b>؛ وفي المحايد: <b>أيّ، ما؟</b>، ويُستعمل في الاستفهام المباشر وغير المباشر. <s n=\"I.\">اسمًا: <s n=\"1.\">مذكرًا ومؤنثًا: <g>τίς</g>؛ <b>مَن، ما؟</b>، <r v=\"Matt.3.7\"></r>، <r v=\"Matt.26.68\"></r>؛ <r v=\"Mark.11.28\"></r>، <r v=\"Luke.9.9\"></r>، وفي مواضع أخرى كثيرة؛ مع المضاف إليه التبعيضي، <r v=\"Acts.7.52\"></r>، <r v=\"Heb.1.5\"></r>، وفي مواضع أخرى؛ يليه <g>ἐκ</g> (= المضاف إليه التبعيضي)، <r v=\"Matt.6.27\"></r>، <r v=\"Luke.14.28\"></r>، <r v=\"John.8.46\"></r>؛ بمعنى <g>ποῖος</g>، <r v=\"Mark.4.41\"></r>، <r v=\"Mark.6.2\"></r>، <r v=\"Luke.19.3\"></r>، <r v=\"Acts.17.19\"></r>، وفي مواضع أخرى؛ بمعنى <g>πότερος</g>، <r v=\"Matt.21.31\"></r>، <r v=\"Matt.27.17\"></r>، <r v=\"Luke.22.27\"></r>، وفي مواضع أخرى؛ بمعنى <g>ὅς</g> أو <g>ὅστις</g>، <r v=\"Acts.13.25\"></r>. </s> <s n=\"2.\">المحايد: <g>τί</g>؛ <b>ماذا؟</b>، <r v=\"Matt.5.47\"></r>، <r v=\"Matt.11.7\"></r>، <r v=\"Mark.10.3\"></r>، وفي مواضع أخرى؛ <g>χάριν τίνος</g>، <r v=\"1John.3.12\"></r>؛ <g>διὰ τί</g>، <r v=\"Matt.9.11\"></r>، وفي مواضع أخرى؛ <g>εἰς τί</g>، <r v=\"Matt.14.31\"></r>، وفي مواضع أخرى؛ بالحذف: <g>ἵνα τί</g> (بتقدير <g>γένηται</g>)، <b>لماذا</b>، <r v=\"Matt.9.5\"></r>، وفي مواضع أخرى؛ <g>τί οὖν</g>، <r v=\"Rom.3.9\"></r>، <r v=\"Rom.6.1\"></r>، <r v=\"Rom.6.15\"></r>، <r v=\"1Cor.14.15\"></r>، وفي مواضع أخرى؛ <g>τί γάρ</g>، <r v=\"Rom.3.3\"></r>، <r v=\"Phil.1.8\"></r>؛ <g>τί ἐμοὶ (ὑμῖν) καὶ σοί</g>، انظر تحت مدخل <g>ἔγω</g>. </s> </s> <s n=\"II.\">صفةً: <b>مَن؟ ما؟ أيّ؟</b>، <r v=\"Matt.5.46\"></r>، <r v=\"Luke.14.31\"></r>، <r v=\"John.2.18\"></r>، وفي مواضع أخرى. </s> <s n=\"III.\">ظرفًا: بمعنى <g>διὰ τι (τί ὅτι)</g>، <b>لماذا</b>، <r v=\"Matt.6.28\"></r>، <r v=\"Mark.4.40\"></r>، <r v=\"Luke.6.46\"></r>، <r v=\"John.18.23\"></r>، وفي مواضع أخرى؛ في الأسئلة البلاغية بمعنى النفي، <r v=\"Matt.27.4\"></r>، <r v=\"John.21.22\"></r>، <r v=\"John.21.23\"></r>، <r v=\"1Cor.5.12\"></r>، <r v=\"1Cor.7.16\"></r>، وفي مواضع أخرى؛ وفي التعجب (مثل العبرية <h n=\"H4100\">מָה</h>)، <b>ما أشدَّ، كم</b> (<r v=\"2Kgs.6.20\"></r>، <r v=\"Ps.3.2\"></r>، وفي مواضع أخرى)، <r v=\"Luke.12.49\"></r>.</s> </s>","en":"<f><o>τίς</o>, neut., <g>τί</g>, gen., <g>τίνος</g>, interrog. pron., [in LXX for <h n=\"H4100,H4310\">מָה ,מִי</h> ;] in masc. and fem., </f> <s><b>who, which, what?</b>; in neut., <b>which, what?</b>, used both in direct and in indirect questions. <s n=\"I.\">As subst., <s n=\"1.\">masc., fem.: <g>τίς</g>; <b>who, what?</b>, <r v=\"Matt.3.7\"></r> <r v=\"Matt.26.68\"></r>; <r v=\"Mark.11.28\"></r>, <r v=\"Luke.9.9\"></r>, al. mult.; c. gen. partit., <r v=\"Acts.7.52\"></r>, <r v=\"Heb.1.5\"></r>, al; seq. <g>ἐκ</g> (= gen. partit.), <r v=\"Matt.6.27\"></r>, <r v=\"Luke.14.28\"></r>, <r v=\"John.8.46\"></r>; = <g>ποῖος</g>, <r v=\"Mark.4.41\"></r> <r v=\"Mark.6.2\"></r>, <r v=\"Luke.19.3\"></r>, <r v=\"Acts.17.19\"></r>, al.; = <g>πότερος</g> (M, <i>Pr.</i>, 77), <r v=\"Matt.21.31\"></r> <r v=\"Matt.27.17\"></r>, <r v=\"Luke.22.27\"></r>, al.; = <g>ὅς</g> or <g>ὅστις</g> (rare in cl.; cf. Bl., §50, 5; M, <i>Pr.</i>, 93), <r v=\"Acts.13.25\"></r>. </s> <s n=\"2.\">Neut.: <g>τί</g>; <b>what?</b>, <r v=\"Matt.5.47\"></r> <r v=\"Matt.11.7\"></r>, <r v=\"Mark.10.3\"></r>, al.; <g>χάριν τίνος</g>, <r v=\"1John.3.12\"></r>; <g>διὰ τί</g>, <r v=\"Matt.9.11\"></r>, al.; <g>εἰς τί</g>, <r v=\"Matt.14.31\"></r>, al.; elliptically, <g>ἵνα τί</g> (sc. <g>γένηται</g>), <b>why</b>, <r v=\"Matt.9.5\"></r>, al.; <g>τί οὖν</g>, <r v=\"Rom.3.9\"></r> <r v=\"Rom.6.1\"></r>, <r v=\"Rom.6.15\"></r> <r v=\"1Cor.14.15\"></r>, al.; <g>τί γάρ</g>, <r v=\"Rom.3.3\"></r>, <r v=\"Phil.1.8\"></r>; <g>τί ἐμοὶ (ὑμῖν) καὶ σοί</g>, v.s. <g>ἔγω</g>. </s> </s> <s n=\"II.\">As adj.: <b>who? what? which?</b>, <r v=\"Matt.5.46\"></r>, <r v=\"Luke.14.31\"></r>, <r v=\"John.2.18\"></r>, al. </s> <s n=\"III.\">As adv.: = <g>διὰ τι (τί ὅτι)</g>, <b>why</b>, <r v=\"Matt.6.28\"></r>, <r v=\"Mark.4.40\"></r>, <r v=\"Luke.6.46\"></r>, <r v=\"John.18.23\"></r>, al.; in rhet. questions, = a negation, <r v=\"Matt.27.4\"></r>, <r v=\"John.21.22\"></r>, <r v=\"John.21.23\"></r> <r v=\"1Cor.5.12\"></r> <r v=\"1Cor.7.16\"></r>, al. in exclamations (like Heb. <h n=\"H4100\">מָה</h>), <b>how</b> (<r v=\"2Kgs.6.20\"></r>, <r v=\"Ps.3.2\"></r>, al.), <r v=\"Luke.12.49\"></r>.</s> </s>"},"G5151":{"l":"τρίς","o":12,"ar":"<f><o>τρίς</o></f> ظرف، <s><b>ثلاث مرات</b>: <r v=\"Matt.26.34\"></r>، <r v=\"Matt.26.75\"></r>، <r v=\"Mark.14.30\"></r>، <r v=\"Mark.14.72\"></r>، <r v=\"Luke.22.34\"></r>، <r v=\"Luke.22.61\"></r>، <r v=\"John.13.38\"></r>، <r v=\"2Cor.11.25\"></r> <r v=\"2Cor.12.8\"></r>؛ <g>ἐπὶ τ.</g>، <r v=\"Acts.10.16\"></r> <r v=\"Acts.11.10\"></r>.†</s>","en":"<f><o>τρίς</o></f> <et> <e t=\"derivation\">(&lt; <g>τρεῖς</g>), </e> </et> adv., <s><b>thrice</b>: <r v=\"Matt.26.34\"></r>, <r v=\"Matt.26.75\"></r>, <r v=\"Mark.14.30\"></r>, <r v=\"Mark.14.72\"></r>, <r v=\"Luke.22.34\"></r>, <r v=\"Luke.22.61\"></r>, <r v=\"John.13.38\"></r>, <r v=\"2Cor.11.25\"></r> <r v=\"2Cor.12.8\"></r>; <g>ἐπὶ τ.</g>, <r v=\"Acts.10.16\"></r> <r v=\"Acts.11.10\"></r>.†</s>"},"G5177":{"l":"τυγχάνω","o":12,"ar":"<f><o>τυγχάνω </o></f> <s n=\"I.\">متعدٍّ. </s> <s n=\"1.\">في اليونانية الكلاسيكية: <b>أصاب</b> الهدف (عكس <g>ἁμαρτάνω</g>: <i>أخطأ الهدف</i>). </s> <s n=\"2.\"><b>عثر على، صادف</b>؛ </s> <s n=\"(a)\">عن الأشخاص: <b>لقي، التقى بـ</b>: مطلقًا، اسم الفاعل <g>ὁ τυχών</g>: <b>شخص عابر، أيّ أحد</b> (باللاتينية <l>quivis</l>)، <g>οὐ τυχών</g>: <b>غير عادي</b> أو <b>غير مألوف</b>، <r v=\"Acts.19.11\"></r>، <r v=\"Acts.28.2\"></r>؛ </s> <s n=\"(b)\">عن الأشياء: <b>بلغ، نال، حصل على</b>: مع مضاف إليه الشيء، <r v=\"Luke.20.35\"></r>، <r v=\"Acts.24.3\"></r>، <r v=\"Acts.26.22\"></r>، <r v=\"Acts.27.3\"></r>، <r v=\"2Tim.2.10\"></r>، <r v=\"Heb.8.6\"></r>، <r v=\"Heb.11.35\"></r>. </s> <s n=\"II.\">لازم: <b>حدث</b>؛ عن الأشياء: <b>حدث، اتّفق، أصاب</b>: غير شخصي، <g>εἰ τύχοι</g>: <b>ربما، لعلّه</b>، <r v=\"1Cor.14.10\"></r>، <r v=\"1Cor.15.37\"></r>؛ وكذلك اسم الفاعل <g>τυχόν</g> (منصوب مطلق قديم)، <r v=\"1Cor.16.6\"></r> </s>","en":"<f><o>τυγχάνω </o></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.19.5\"></r> (<h n=\"H4672\">מָצָא</h>), <r v=\"Job.3.21\"></r> <r v=\"Job.7.2\"></r> <r v=\"Job.17.1\"></r>, <r v=\"Prov.30.23\"></r> (without definite Heb. equiv.), <r v=\"Wis.15.19\"></r>, <r v=\"1Macc.11.42\"></r>, <r v=\"3Macc.3.7\"></r>, al. ;] </e> </et> <s n=\"I.\">Trans. </s> <s n=\"1.\"><b>to hit</b> (opp. to <g>ἁμαρτάνω</g>, <i>to miss the mark</i>: Hom., Xen., al.). </s> <s n=\"2.\"><b>to hit upon, light upon</b>; </s> <s n=\"(a)\">of persons, <b>to meet with, fall in with</b>: absol., ptcp., <g>ὁ τυχών</g>, <b>a chance person, anyone</b> (Lat. <l>quivis</l>), <g>οὐ τυχών</g>, <b>not common</b> or <b>ordinary</b>, <r v=\"Acts.19.11\"></r> <r v=\"Acts.28.2\"></r>; </s> <s n=\"(b)\">of things, <b>to reach, get, obtain</b>: c. gen. rei. <r v=\"Luke.20.35\"></r>, <r v=\"Acts.24.3\"></r> <r v=\"Acts.26.22\"></r> <r v=\"Acts.27.3\"></r>, <r v=\"2Tim.2.10\"></r> <r v=\"Heb.8.6\"></r> <r v=\"Heb.11.35\"></r>. </s> <s n=\"II.\">Intrans., <b>to happen</b>; of things, <b>to happen, chance, befall</b>: impers., <g>εἰ τύχοι</g>, <b>it may be, perhaps</b>, <r v=\"1Cor.14.10\"></r> <r v=\"1Cor.15.37\"></r>; so ptcp., <g>τυχόν</g> (old acc. absol.; v. M, <i>Pr.</i>, 74), <r v=\"1Cor.16.6\"></r> </s> <et> <e t=\"derivation\">(cf. <g>ἐν-</g>, <g>ὑπερ-εν-</g>, <g>ἐπι-</g>, <g>παρα-</g>, <g>συν-τυγχάνω</g>).†</e> </et>"},"G5132":{"l":"τράπεζα","o":15,"ar":"<f><o>τράπεζα</o>، <g>-ης, ἡ </g></f> <s n=\"1.\"><b>مائدة، مائدة طعام</b>: <r v=\"Matt.15.27\"></r>، <r v=\"Mark.7.28\"></r>، <r v=\"Luke.16.21\"></r>، <r v=\"Luke.19.23\"></r>، <r v=\"Luke.22.21\"></r>، <r v=\"Luke.22.30\"></r>؛ عن مائدة خبز التقدمة، <r v=\"Heb.9.2\"></r>. وكنايةً عن الطعام المقدَّم: <r v=\"Acts.16.34\"></r>، <r v=\"Rom.11.9\"></r> <i>(السبعينية)</i>، <r v=\"1Cor.10.21\"></r>؛ <g>διακονεῖν ταῖς τ.</g>، <r v=\"Acts.6.2\"></r>. </s> <s n=\"2.\"><b>مائدة</b> الصيارفة، <b>مصرف</b>: <r v=\"Matt.21.12\"></r>، <r v=\"Mark.11.15\"></r>، <r v=\"Luke.19.23\"></r>، <r v=\"John.2.15\"></r>؛ وكذلك بحسب أحد الآراء في <r v=\"Acts.6.2\"></r>.†</s>","en":"<f><o>τράπεζα</o>, <g>-ης, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7979\">שֻׁלְחָן</h>, also for <h n=\"H3899\">לֶחֶם</h>, etc. ;]</e> </et> <s n=\"1.\"><b>a table, dining-table</b>: <r v=\"Matt.15.27\"></r>, <r v=\"Mark.7.28\"></r>, <r v=\"Luke.16.21\"></r> <r v=\"Luke.19.23\"></r> <r v=\"Luke.22.21\"></r>, <r v=\"Luke.22.30\"></r>; of the table of shewbread, <r v=\"Heb.9.2\"></r>. By meton., of food provided (v. <i>DB</i>, iv, 670 a): <r v=\"Acts.16.34\"></r>, <r v=\"Rom.11.9\"></r> <i>(LXX)</i> <r v=\"1Cor.10.21\"></r>; <g>διακονεῖν ταῖς τ.</g>, <r v=\"Acts.6.2\"></r> (cf. Page, in l., but v. infr.). </s> <s n=\"2.\">A money-changer's <b>table, a bank</b> (Dem., Arist., al.): <r v=\"Matt.21.12\"></r>, <r v=\"Mark.11.15\"></r>, <r v=\"Luke.19.23\"></r>, <r v=\"John.2.15\"></r>; so also acc to Dr. Field (<i>Notes</i>, 113), <r v=\"Acts.6.2\"></r> (but v. supr.).†</s>"},"G5198":{"l":"ὑγιαίνω","o":12,"ar":"<f><o>ὑγιαίνω</o> </f> <s><b>كان سليمًا، معافًى، في صحة جيدة</b>: <r v=\"Luke.5.31\"></r>، <r v=\"Luke.7.10\"></r>، <r v=\"Luke.15.27\"></r>، <r v=\"3John.1.2\"></r>. وفي الرسائل الرعوية مجازيًا: <g>ὑ. ἐν τ. πίστει</g>، <r v=\"Titus.1.13\"></r>؛ <g>τ. πίστει</g>، <g>τ. ἀγάπῃ</g>، <g>τ. ὑπομονῇ</g>، <r v=\"Titus.2.2\"></r>؛ <g>ἡ ὑγιαίνουσα διδασκαλία</g>، <r v=\"1Tim.1.10\"></r>، <r v=\"2Tim.4.3\"></r>، <r v=\"Titus.1.9\"></r>، <r v=\"Titus.2.1\"></r>؛ <g>λόγοι ὑγιαίνοντες</g>، <r v=\"1Tim.6.3\"></r>، <r v=\"2Tim.1.13\"></r>.†</s>","en":"<f><o>ὑγιαίνω</o> </f> <et> <e t=\"derivation\">(&lt; <g>ὑγιής</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7965\">שָׁלוֹם</h>, and freq. in To ;]</e> </et> <s><b>to be sound, healthy, in good health</b>: <r v=\"Luke.5.31\"></r> <r v=\"Luke.7.10\"></r> <r v=\"Luke.15.27\"></r>, <r v=\"3John.1.2\"></r>. In Past. Epp. (as also in cl.) metaph., <g>ὑ. ἐν τ. πίστει</g>, <r v=\"Titus.1.13\"></r> ; <g>τ. πίστει</g>, <g>τ. ἀγάπῃ</g>, <g>τ. ὑπομονῇ</g>, <r v=\"Titus.2.2\"></r>; <g>ἡ ὑγιαίνουσα διδασκαλία</g>, <r v=\"1Tim.1.10\"></r>, <r v=\"2Tim.4.3\"></r>, <r v=\"Titus.1.9\"></r> <r v=\"Titus.2.1\"></r> ; <g>λόγοι ὑγιαίνοντες</g>, <r v=\"1Tim.6.3\"></r> , <r v=\"2Tim.1.13\"></r>.†</s>"},"G5195":{"l":"ὑβρίζω","o":5,"ar":"<f><o>ὑβρίζω</o></f> <s n=\"1.\">لازم: <b>تجبّر، طغى</b>. </s> <s n=\"2.\">متعدٍّ: <b>أهان، شتم، عامل بوقاحة</b>: مع منصوب الشخص، <r v=\"Matt.22.6\"></r>، <r v=\"Luke.11.45\"></r>، <r v=\"Luke.18.32\"></r>، <r v=\"Acts.14.5\"></r>، <r v=\"1Thess.2.2\"></r>.†</s>","en":"<f><o>ὑβρίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>ὕβρις</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H1343\">גֵּאֶה</h>, etc. ;] </e> </et> <s n=\"1.\">intrans., <b>to wax wanton, run riot</b>. </s> <s n=\"2.\">Trans., <b>to outrage, insult, treat insolently</b>: c. acc pers., <r v=\"Matt.22.6\"></r>, <r v=\"Luke.11.45\"></r> <r v=\"Luke.18.32\"></r>, <r v=\"Acts.14.5\"></r>, <r v=\"1Thess.2.2\"></r>.†</s>"},"G5111":{"l":"τολμάω","o":16,"ar":"<f><o>τολμάω</o>، <g>-ῶ </g></f> <s><b>تشجّع، تجاسر، جرؤ، كان جريئًا</b>: مطلقًا، <r v=\"2Cor.11.21\"></r>؛ يليه <g>ἐπί</g>، <r v=\"2Cor.10.2\"></r>؛ مع المصدر، <r v=\"Matt.22.46\"></r>، <r v=\"Mark.12.34\"></r>، <r v=\"Luke.20.40\"></r>، <r v=\"John.21.12\"></r>، <r v=\"Acts.5.13\"></r> <r v=\"Acts.7.32\"></r>، <r v=\"Rom.15.18\"></r>، <r v=\"1Cor.6.1\"></r>، <r v=\"2Cor.10.12\"></r>، <r v=\"Phil.1.14\"></r>، <r v=\"Jude.1.9\"></r>؛ <b>أقدم على</b>، <r v=\"Rom.5.7\"></r>؛ <g>τολμήσας εἰσῆλθεν</g>، <b>تجاسر ودخل</b>، <r v=\"Mark.15.43\"></r> (قارن <g>ἀπο-τολμάω</g>).†</s>","en":"<f><o>τολμάω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.15.12\"></r> (<h n=\"H3947\">לָקַח</h>), <r v=\"Esth.1.18\"></r> <r v=\"Esth.7.5\"></r> (<h n=\"H3820\">לֵב</h> <h n=\"H4390\">מָלֵא</h>) <r v=\"Jdt.14.13\"></r>, <r v=\"2Macc.4.2\"></r>, <r v=\"3Macc.3.21\"></r> R, <r v=\"4Macc.8.18\"></r> * ;]</e> </et> <s><b>to have courage, to venture, dare, be bold</b>: absol, <r v=\"2Cor.11.21\"></r>; seq. <g>ἐπί</g>, <r v=\"2Cor.10.2\"></r>; c. inf. (Bl., § 69, 4), <r v=\"Matt.22.46\"></r>, <r v=\"Mark.12.34\"></r>, <r v=\"Luke.20.40\"></r>, <r v=\"John.21.12\"></r>, <r v=\"Acts.5.13\"></r> <r v=\"Acts.7.32\"></r>, <r v=\"Rom.15.18\"></r>, <r v=\"1Cor.6.1\"></r>, <r v=\"2Cor.10.12\"></r>, <r v=\"Phil.1.14\"></r>, <r v=\"Jude.1.9\"></r>; <b>to submit to</b> (in cl. usually absol. in this sense), <r v=\"Rom.5.7\"></r> (v. Field, <i>Notes</i>, 155); <g>τολμήσας εἰσῆλθεν</g>, <b>took courage and went in</b> (v. Field, <i>op. cit.</i>, 44), <r v=\"Mark.15.43\"></r> (cf. <g>ἀπο-τολμάω</g>).†</s>"},"G5196":{"l":"ὕβρις","o":3,"ar":"<f><o>ὕβρις</o>، <g>-εως, ἡ </g></f> <s n=\"1.\"><b>عجرفة، تجبّر</b>. </s> <s n=\"2.\">= <g>ὕβρισμα</g>، <b>فعل عنف متعجرف، إهانة، ضرر</b>: <r v=\"2Cor.12.10\"></r>؛ مجازيًا، عن خسارة في البحر، <r v=\"Acts.27.10\"></r>، <r v=\"Acts.27.21\"></r>.†</s>","en":"<f><o>ὕβρις</o>, <g>-εως, ἡ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1347\">גָּאוֹן</h> and cogn. forms ;]</e> </et> <s n=\"1.\"><b>wantonness, insolence</b>. </s> <s n=\"2.\">= <g>ὕβρισμα</g>, <b>an act of wanton violence, an outrage, injury</b>: <r v=\"2Cor.12.10\"></r>; metaph., of a loss by sea (Pind.), <r v=\"Acts.27.10\"></r>, <r v=\"Acts.27.21\"></r> (v. MM, xxv).†</s>"},"G5140":{"l":"τρεῖς","o":68,"ar":"<f><o>τρεῖς</o>، <g>οἱ, αἱ, τρία, τά</g></f> <s><b>ثلاثة</b>: <r v=\"Matt.12.40\"></r>، وفي مواضع أخرى؛ <g>μετὰ τ. ἡμέρας</g> = <g>τῇ τρίτῃ ἡ.</g>، <r v=\"Mark.10.34\"></r>، وفي مواضع أخرى. </s>","en":"<f><o>τρεῖς</o>, <g>οἱ, αἱ, τρία, τά</g></f> <s><b>three</b>: <r v=\"Matt.12.40\"></r>, al.; <g>μετὰ τ. ἡμέρας</g> = <g>τῇ τρίτῃ ἡ.</g>, <r v=\"Mark.10.34\"></r>, al. (cf. Field, <i>Notes</i>, 11 ff.) </s>"},"G5119":{"l":"τότε","o":160,"ar":"<f><o>τότε</o>، ظرف زمان للإشارة، مقابل <g>ὅτε</g>، </f> <s><b>حينئذٍ، في ذلك الوقت</b>؛ <s n=\"(a)\">عن أحداث متزامنة: <r v=\"Matt.2.17\"></r> <r v=\"Matt.3.5\"></r> وكثيرًا، <r v=\"Rom.6.21\"></r>؛ يليه اسم الفاعل، <r v=\"Matt.2.16\"></r>، <r v=\"Gal.4.8\"></r>؛ عكس <g>νῦν</g>، <r v=\"Gal.4.29\"></r>، <r v=\"Heb.12.26\"></r>؛ <g>ὁ τ. κόσμος</g> (العالم الكائن حينئذٍ)، <r v=\"2Pet.3.6\"></r>؛ </s> <s n=\"(b)\">عن أحداث لاحقة: <b>حينئذٍ، عندئذٍ، ثم</b>: <r v=\"Matt.2.7\"></r> <r v=\"Matt.3.5\"></r> <r v=\"Matt.4.1\"></r> وكثيرًا، <r v=\"Luke.11.26\"></r>؛ <g>τ. οὖν</g>، <r v=\"John.11.14\"></r> <r v=\"John.19.1\"></r>، <r v=\"John.19.16\"></r> <r v=\"John.20.8\"></r>؛ <g>εὐθέως τ.</g>، <r v=\"Acts.17.14\"></r>؛ <g>ὅτε . . . τ.</g>، <r v=\"Matt.13.26\"></r> <r v=\"Matt.21.1\"></r>، <r v=\"John.12.16\"></r>؛ <g>ἀπὸ τ.</g> (من ذلك الوقت)، <r v=\"Matt.4.17\"></r> <r v=\"Matt.16.21\"></r> <r v=\"Matt.26.16\"></r>، <r v=\"Luke.16.16\"></r>؛ </s> <s n=\"(c)\">عن أمور مستقبلة: <r v=\"Matt.24.23\"></r>، <r v=\"Matt.24.40\"></r> <r v=\"Matt.25.1\"></r>، <r v=\"Matt.15.31\"></r><i>وما يليه</i>؛ عكس <g>ἄρτι</g>، <r v=\"1Cor.13.12\"></r>؛ <g>καὶ τ.</g>، <r v=\"Matt.7.23\"></r>، <r v=\"Mark.13.21\"></r>، <r v=\"Luke.21.27\"></r>، <r v=\"1Cor.4.5\"></r>، وفي مواضع أخرى؛ <g>ὅταν . . . τ.</g>، <r v=\"Matt.9.15\"></r>، <r v=\"Mark.2.20\"></r>، <r v=\"Luke.5.35\"></r>، <r v=\"1Thess.5.3\"></r>، وفي مواضع أخرى (وهو أكثر ورودًا في إنجيل متى منه في بقية العهد الجديد). </s> </s>","en":"<f><o>τότε</o>, demonstr. adv. of time, correlat. of <g>ὅτε</g>, </f> <s><b>then, at that time</b>; <s n=\"(a)\">of concurrent events: <r v=\"Matt.2.17\"></r> <r v=\"Matt.3.5\"></r> and freq., <r v=\"Rom.6.21\"></r>; seq. ptcp., <r v=\"Matt.2.16\"></r>, <r v=\"Gal.4.8\"></r>; opp. to <g>νῦν</g>, <r v=\"Gal.4.29\"></r>, <r v=\"Heb.12.26\"></r>; <g>ὁ τ. κόσμος</g>, <r v=\"2Pet.3.6\"></r>; </s> <s n=\"(b)\">of consequent events, <b>then, thereupon</b>: <r v=\"Matt.2.7\"></r> <r v=\"Matt.3.5\"></r> <r v=\"Matt.4.1\"></r> and freq., <r v=\"Luke.11.26\"></r>; <g>τ. οὖν</g>, <r v=\"John.11.14\"></r> <r v=\"John.19.1\"></r>, <r v=\"John.19.16\"></r> <r v=\"John.20.8\"></r>; <g>εὐθέως τ.</g>, <r v=\"Acts.17.14\"></r>; <g>ὅτε . . . τ.</g>, <r v=\"Matt.13.26\"></r> <r v=\"Matt.21.1\"></r>, <r v=\"John.12.16\"></r>; <g>ἀπὸ τ.</g>, <r v=\"Matt.4.17\"></r> <r v=\"Matt.16.21\"></r> <r v=\"Matt.26.16\"></r>, <r v=\"Luke.16.16\"></r>; </s> <s n=\"(c)\">of things future: <r v=\"Matt.24.23\"></r>, <r v=\"Matt.24.40\"></r> <r v=\"Matt.25.1\"></r>, <r v=\"Matt.15.31\"></r><i>ff.</i>; opp. to <g>ἄρτι</g>, <r v=\"1Cor.13.12\"></r>; <g>καὶ τ.</g>, <r v=\"Matt.7.23\"></r>, <r v=\"Mark.13.21\"></r>, <r v=\"Luke.21.27\"></r>, <r v=\"1Cor.4.5\"></r>, al.; <g>ὅταν . . . τ.</g>, <r v=\"Matt.9.15\"></r>, <r v=\"Mark.2.20\"></r>, <r v=\"Luke.5.35\"></r>, <r v=\"1Thess.5.3\"></r>, al. (more freq. in Mt than in the rest of the NT). </s> </s>"},"G5121":{"l":"τοὐναντίον","o":3,"ar":"<f><o>τοὐναντίον </o></f> <s>بالإدغام عن <g>τὸ ἐνανίον</g>، محايد منصوب يُستعمل ظرفًا: <b>بالعكس، على خلاف ذلك</b>: <r v=\"2Cor.2.7\"></r>، <r v=\"Gal.2.7\"></r>، <r v=\"1Pet.3.9\"></r>.†</s>","en":"<f><o>τοὐναντίον </o></f> <s>by crasis for <g>τὸ ἐνανίον</g>, neut. acc, used adverbially, <b>on the contrary, contrariwise</b>: <r v=\"2Cor.2.7\"></r>, <r v=\"Gal.2.7\"></r>, <r v=\"1Pet.3.9\"></r>.†</s>"},"G5180":{"l":"τύπτω","o":13,"ar":"<f><o>τύπτω </o></f> <s><b>يضرب، يلطم، يقرع</b>: مع المنصوب، <r v=\"Matt.24.49\"></r>، <r v=\"Mark.15.19\"></r>، <r v=\"Luke.12.45\"></r>، <r v=\"Acts.18.17\"></r>، <r v=\"Acts.21.32\"></r>، <r v=\"Acts.23.2\"></r>، <r v=\"Acts.23.3\"></r>؛ عن النائحين، <g>τὰ στήθη</g>، <r v=\"Luke.18.13\"></r>، <r v=\"Luke.23.48\"></r>؛ <g>ἐπὶ τ. σιαγόνα</g>، <r v=\"Luke.6.29\"></r>؛ <g>εἰς τ. κεφαλήν</g>، <r v=\"Matt.27.30\"></r>. مجازيًا، عن إنزال الله الشر: <r v=\"Acts.23.3\"></r> (قارن <r v=\"Exod.8.2\"></r>، <r v=\"Ezek.7.9\"></r>، وفي مواضع أخرى)؛ عن إيلام الضمير، <r v=\"1Cor.8.12\"></r>.†</s>","en":"<f><o>τύπτω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5217\">נכה</h> hi. ;]</e> </et> <s><b>to strike, smite, beat</b>: c. acc, <r v=\"Matt.24.49\"></r>, <r v=\"Mark.15.19\"></r>, <r v=\"Luke.12.45\"></r>, <r v=\"Acts.18.17\"></r> <r v=\"Acts.21.32\"></r> <r v=\"Acts.23.2\"></r>, <r v=\"Acts.23.3\"></r>; of mourners, <g>τὰ στήθη</g>, <r v=\"Luke.18.13\"></r> <r v=\"Luke.23.48\"></r>; <g>ἐπὶ τ. σιαγόνα</g>, <r v=\"Luke.6.29\"></r>; <g>εἰς τ. κεφαλήν</g>, <r v=\"Matt.27.30\"></r>. Metaph., of God inflicting evil: <r v=\"Acts.23.3\"></r> (cf. <r v=\"Exod.8.2\"></r>, <r v=\"Ezek.7.9\"></r>, al.); of disquieting conscience, <r v=\"1Cor.8.12\"></r>.†</s>"},"G5158":{"l":"τρόπος","o":13,"ar":"<f><o>τρόπος</o>، <g>-ου, ὁ</g></f> <s n=\"1.\"><b>طريقة، كيفية، أسلوب</b>: <r v=\"Matt.23.37\"></r>، <r v=\"Luke.13.34\"></r>، <r v=\"Acts.1.11\"></r>، <r v=\"Acts.7.28\"></r>، <r v=\"2Tim.3.8\"></r>، <r v=\"Jude.1.7\"></r>؛ <g>καθ’ ὃν τ.</g>: <r v=\"Acts.15.11\"></r>، <r v=\"Acts.27.25\"></r>؛ <g>κατὰ πάντα τ.</g>: <r v=\"Rom.3.2\"></r>؛ <g>κατὰ μηδένα τ.</g> (<r v=\"4Macc.4.24\"></r>، وفي مواضع أخرى): <r v=\"2Thess.2.3\"></r>؛ (<g>ἐν</g>) <g>παντὶ τ.</g>: <r v=\"Phil.1.18\"></r>، <r v=\"2Thess.3.16\"></r> </s> <s n=\"2.\">عن الأشخاص: <b>سيرة، خُلُق</b>: <r v=\"Heb.13.5\"></r>.†</s>","en":"<f><o>τρόπος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>τρέπω</g>), </e> <e t=\"septuagint\">[in LXX chiefly (<g>ὃν τ.</g>) for <h n=\"H834\">כַּאֲשֶׁר</h> ;]</e> </et> <s n=\"1.\"><b>a way, manner, fashion</b>: <r v=\"Matt.23.37\"></r>, <r v=\"Luke.13.34\"></r>, <r v=\"Acts.1.11\"></r> <r v=\"Acts.7.28\"></r>, <r v=\"2Tim.3.8\"></r>, <r v=\"Jude.1.7\"></r>; <g>καθ’ ὃν τ.</g>, <r v=\"Acts.15.11\"></r> <r v=\"Acts.27.25\"></r> (cf. MM, xxv); <g>κατὰ πάντα τ.</g>, <r v=\"Rom.3.2\"></r>; <g>κατὰ μηδένα τ.</g> (<r v=\"4Macc.4.24\"></r>, al.), <r v=\"2Thess.2.3\"></r>; (<g>ἐν</g>) <g>παντὶ τ.</g>, <r v=\"Phil.1.18\"></r>, <r v=\"2Thess.3.16\"></r> </s> <s n=\"2.\">Of persons, <b>manner of life, character</b> (Hdt., Æsch., al.): <r v=\"Heb.13.5\"></r>.†</s>"},"G5103":{"l":"Τίτος","o":13,"ar":"<f><o>Τίτος</o>، <g>-ου, ὁ </g></f> <s><b>تيطس</b>؛ </s> <s n=\"1.\">تلميذ القديس بولس ورفيقه: <r v=\"2Cor.2.13\"></r>، <r v=\"2Cor.7.6\"></r>، <r v=\"2Cor.7.13\"></r>، <r v=\"2Cor.7.14\"></r>، <r v=\"2Cor.8.6\"></r>، <r v=\"2Cor.8.16\"></r>، <r v=\"2Cor.8.23\"></r>، <r v=\"2Cor.12.18\"></r>، <r v=\"Gal.2.1\"></r>، <r v=\"Gal.2.3\"></r>، <r v=\"2Tim.4.10\"></r>، <r v=\"Titus.1.4\"></r>. </s> <s n=\"2.\">رجل يُلقَّب يُسطُس: <r v=\"Acts.18.7\"></r>.†</s>","en":"<f><o>Τίτος</o>, <g>-ου, ὁ </g></f> <s><b>Titus</b>; </s> <s n=\"1.\">St. Paul's disciple and companion: <r v=\"2Cor.2.13\"></r> <r v=\"2Cor.7.6\"></r>, <r v=\"2Cor.7.13\"></r>, <r v=\"2Cor.7.14\"></r> <r v=\"2Cor.8.6\"></r>, <r v=\"2Cor.8.16\"></r>, <r v=\"2Cor.8.23\"></r> <r v=\"2Cor.12.18\"></r>, <r v=\"Gal.2.1\"></r>, <r v=\"Gal.2.3\"></r>, <r v=\"2Tim.4.10\"></r>, <r v=\"Titus.1.4\"></r>, <i>subscr</i>., Rec. (<g>Τῖτος</g>). </s> <s n=\"2.\">One surnamed Justus: <r v=\"Acts.18.7\"></r>, RV (T, WH, <g>Τίτιος</g>).†</s>"},"G5185":{"l":"τυφλός","o":50,"ar":"<f><o>τυφλός</o>، <g>-ή, -όν </g></f> <s><b>أعمى</b>: اسمًا، <g>ὁ τ.</g>: <r v=\"Matt.9.27\"></r>، <r v=\"Mark.8.22\"></r>، <r v=\"Luke.4.18\"></r> <i>(السبعينية)</i>، <r v=\"John.5.3\"></r>، وفي مواضع أخرى. مجازيًا: <r v=\"Matt.15.14\"></r>، <r v=\"Matt.23.16-Matt.23.26\"></r>، <r v=\"John.9.39-John.9.41\"></r>، <r v=\"Rom.2.19\"></r>، <r v=\"2Pet.1.9\"></r>، <r v=\"Rev.3.17\"></r>. </s>","en":"<f><o>τυφλός</o>, <g>-ή, -όν </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5787\">עִוֵּר</h> ;] </e> </et> <s><b>blind</b>: as subst., <g>ὁ τ.</g>, <r v=\"Matt.9.27\"></r>, <r v=\"Mark.8.22\"></r>, <r v=\"Luke.4.18\"></r> <i>(LXX)</i>, <r v=\"John.5.3\"></r>, al. Metaph.: <r v=\"Matt.15.14\"></r> <r v=\"Matt.23.16-Matt.23.26\"></r>, <r v=\"John.9.39-John.9.41\"></r>, <r v=\"Rom.2.19\"></r>, <r v=\"2Pet.1.9\"></r>, <r v=\"Rev.3.17\"></r>. </s>"},"G5187":{"l":"τυφόω","o":3,"ar":"<f>* <o>τυφόω</o>، <g>-ῶ</g></f> <s>أصلاً: <b>لفّ بالدخان</b>؛ ولا يُستعمل إلّا مجازيًا: <b>نفخ، أعمى</b> بالكبرياء: المبني للمجهول (<b>تصلّف، تكبّر</b>): <r v=\"1Tim.3.6\"></r>، <r v=\"1Tim.6.4\"></r>، <r v=\"2Tim.3.4\"></r>.†</s>","en":"<f>* <o>τυφόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>τῦφος</g>, <b>smoke</b>; metaph., <b>conceit</b>), </e> </et> <s>prop., <b>to wrap in smoke</b>; used only metaph., <b>to puff up, becloud</b> with pride: pass., <r v=\"1Tim.3.6\"></r> <r v=\"1Tim.6.4\"></r>, <r v=\"2Tim.3.4\"></r> (Dem., Arist., al.).†</s>"},"G5174":{"l":"Τρῳάς","o":6,"ar":"<f><o>Τρῳάς</o>، <g>-άδος, ἡ</g> </f> <s><b>ترواس</b>، مدينة قرب الهلسبنت: <r v=\"Acts.16.8\"></r>، <r v=\"Acts.16.11\"></r> <r v=\"Acts.20.5\"></r>، <r v=\"Acts.20.6\"></r>، <r v=\"2Cor.2.12\"></r>، <r v=\"2Tim.4.13\"></r>.†</s>","en":"<f><o>Τρῳάς</o> (Rec. <g>Τρω-</g>), <g>-άδος, ἡ</g> </f> <s><b>Troas</b>, a city near the Hellespont: <r v=\"Acts.16.8\"></r>, <r v=\"Acts.16.11\"></r> <r v=\"Acts.20.5\"></r>, <r v=\"Acts.20.6\"></r>, <r v=\"2Cor.2.12\"></r>, <r v=\"2Tim.4.13\"></r>.†</s>"},"G5130":{"l":"οὗτος","o":1387,"ar":"<f><o>οὗτος</o>، <g>αὕτη, τοῦτο</g>، حالة الجر: <g>τούτου, ταύτης, τούτου</g>،</f> ضمير إشارة (علاقته بـ <g>ἐκεῖνος</g> كعلاقة <l>hic</l> بـ <l>ille</l>)، <s><b>هذا</b>؛ <s n=\"1.\">بمعنى الاسم: <b>هذا</b>، <b>هو</b>؛ <s n=\"(a)\">مطلقًا: <r v=\"Matt.3.17\"></r>، <r v=\"Mark.9.7\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"Luke.7.45\"></r>، <r v=\"John.1.15\"></r>، <r v=\"Acts.2.15\"></r>، وفي مواضع أخرى؛ للتعبير عن الازدراء، <r v=\"Matt.13.55\"></r>، <r v=\"Matt.13.56\"></r>، <r v=\"Mark.6.2\"></r>، <r v=\"Mark.6.3\"></r>، <r v=\"John.6.42\"></r>، وفي مواضع أخرى؛ <g>εἰς τοῦτο</g>، <r v=\"Mark.1.38\"></r>، <r v=\"Rom.14.9\"></r>؛ <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>؛ قارن <r v=\"John.5.1\"></r>)، <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">بالإشارة إلى ما سبق: <r v=\"Matt.5.19\"></r>، <r v=\"Mark.3.35\"></r>، <r v=\"Luke.9.48\"></r>، <r v=\"John.6.46\"></r>، <r v=\"Rom.7.10\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">بالإشارة إلى ما يلي: يليه <g>ἵνα</g>، <r v=\"Luke.1.43\"></r>، <r v=\"John.3.19\"></r> (وكثيرًا) <r v=\"John.15.8\"></r>، <r v=\"Rom.14.9\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>، <r v=\"Luke.10.11\"></r>، <r v=\"John.9.30\"></r>، <r v=\"Acts.24.14\"></r>، <r v=\"Rom.2.3\"></r>، وفي مواضع أخرى؛ <g>ὅπως</g>، <r v=\"Rom.9.17\"></r>؛ <g>ἐάν</g>، <r v=\"John.13.35\"></r>؛</s> <s n=\"(d)\">تعابير خاصة: <g>τοῦτο μὲν . . . τ. δέ</g>، <b>تارةً ... وتارةً</b>، <r v=\"Heb.10.33\"></r>؛ <g>καὶ τοῦτο</g> (<g>τοῦτον</g>، <g>ταῦτα</g>)، <b>وذلك</b> (<b>وإياه</b>) <b>أيضًا</b>، <r v=\"Rom.13.11\"></r>، <r v=\"1Cor.2.2\"></r>، <r v=\"Heb.11.12\"></r>؛ <g>τοῦτ’ ἐστιν</g>، <b>أي، يعني</b>، <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">صفةً مع الاسم؛ <s n=\"(a)\">مع أداة التعريف <s n=\"(α)\">قبل الأداة: <r v=\"Matt.12.32\"></r>، <r v=\"Mark.9.29\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"John.4.15\"></r>، <r v=\"Rom.11.24\"></r>، <r v=\"Rev.19.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(β)\">بعد الاسم: <r v=\"Matt.3.9\"></r>، <r v=\"Mark.12.16\"></r>، <r v=\"Luke.11.31\"></r>، <r v=\"John.4.13\"></r>، <r v=\"Acts.6.13\"></r>، <r v=\"Rom.15.28\"></r>، <r v=\"1Cor.1.20\"></r>، <r v=\"Rev.2.24\"></r>، وفي مواضع أخرى؛</s> </s> <s n=\"(b)\">مع اسم بدون أداة التعريف (بقوة الخبر): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>، <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>، <r v=\"2Cor.13.1\"></r>.</s> </s> </s>","en":"<f><o>οὗτος</o>, <g>αὕτη, τοῦτο</g>, gen., <g>τούτου, ταύτης, τούτου</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2088\">זֶה</h>, <h n=\"H2063\">זֹאת</h>;]</e> </et> demonstr. pron. (related to <g>ἐκεῖνος</g> as <l>hic</l> to <l>ille</l>), <s><b>this</b>; <s n=\"1.\">as subst., <b>this one</b>, <b>he</b>; <s n=\"(a)\">absol.: <r v=\"Matt.3.17\"></r>, <r v=\"Mark.9.7\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"Luke.7.45\"></r>, <r v=\"John.1.15\"></r>, <r v=\"Acts.2.15\"></r>, al.; expressing contempt (cl.), <r v=\"Matt.13.55\"></r>, <r v=\"Matt.13.56\"></r>, <r v=\"Mark.6.2\"></r>, <r v=\"Mark.6.3\"></r>, <r v=\"John.6.42\"></r>, al.; <g>εἰς τοῦτο</g>, <r v=\"Mark.1.38\"></r>, <r v=\"Rom.14.9\"></r>; <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>; V. Westc. on <r v=\"John.5.1\"></r>), <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>, al.;</s> <s n=\"(b)\">epanaleptic (referring to what precedes): <r v=\"Matt.5.19\"></r>, <r v=\"Mark.3.35\"></r>, <r v=\"Luke.9.48\"></r>, <r v=\"John.6.46\"></r>, <r v=\"Rom.7.10\"></r>, al.;</s> <s n=\"(c)\">proleptic (referring to what follows): seq. <g>ἵνα</g> (Bl., § 69, 6), <r v=\"Luke.1.43\"></r>, <r v=\"John.3.19\"></r> (and freq.) <r v=\"John.15.8\"></r>, <r v=\"Rom.14.9\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Luke.10.11\"></r>, <r v=\"John.9.30\"></r>, <r v=\"Acts.24.14\"></r>, <r v=\"Rom.2.3\"></r>, al.; <g>ὅπως</g>, <r v=\"Rom.9.17\"></r>; <g>ἐάν</g>, <r v=\"John.13.35\"></r>;</s> <s n=\"(d)\">special idioms: <g>τοῦτο μὲν . . . τ. δέ</g> (cl), <b>partly . . . partly</b>, <r v=\"Heb.10.33\"></r>; <g>καὶ τοῦτο</g> (<g>τοῦτον</g>, <g>ταῦτα</g>), <b>and that</b> (<b>him</b>) <b>too</b>, <r v=\"Rom.13.11\"></r>, <r v=\"1Cor.2.2\"></r>, <r v=\"Heb.11.12\"></r>; <g>τοῦτ’ ἐστιν</g>, <b>that is to say</b>, <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">As adj., c. subst.; <s n=\"(a)\">c. art. <s n=\"(α)\">before the art.: <r v=\"Matt.12.32\"></r>, <r v=\"Mark.9.29\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"John.4.15\"></r>, <r v=\"Rom.11.24\"></r>, <r v=\"Rev.19.9\"></r>, al.;</s> <s n=\"(β)\">after the noun: <r v=\"Matt.3.9\"></r>, <r v=\"Mark.12.16\"></r>, <r v=\"Luke.11.31\"></r>, <r v=\"John.4.13\"></r>, <r v=\"Acts.6.13\"></r>, <r v=\"Rom.15.28\"></r>, <r v=\"1Cor.1.20\"></r>, <r v=\"Rev.2.24\"></r>, al.;</s> </s> <s n=\"(b)\">c. subst. anarth. (with predicative force; Bl., § 49, 4): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>, <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>, <r v=\"2Cor.13.1\"></r>.</s> </s> </s>"},"G5143":{"l":"τρέχω","o":20,"ar":"<f><o>τρέχω </o></f> <s><b>ركض، جرى</b>: <r v=\"Mark.5.6\"></r>، <r v=\"John.20.2\"></r>، <r v=\"John.20.4\"></r>، <r v=\"1Cor.9.24\"></r>، <r v=\"1Cor.9.26\"></r>؛ مع المصدر، <r v=\"Matt.28.8\"></r>؛ يليه <g>ἐπί</g>، <r v=\"Luke.24.12\"></r>؛ <g>εἰς</g>، <r v=\"Rev.9.9\"></r>؛ اسم الفاعل <g>δραμών</g> مع الإخباري، <r v=\"Matt.27.48\"></r>، <r v=\"Mark.15.36\"></r>، <r v=\"Luke.15.20\"></r>. مجازيًا، مأخوذًا من المتسابقين في الجري، عن السرعة أو عن السعي لبلوغ غاية: <r v=\"Rom.9.16\"></r>، <r v=\"Gal.2.2\"></r> <r v=\"Gal.5.7\"></r>، <r v=\"Phil.2.16\"></r>؛ <g>τ. ἀγῶνα</g>، <r v=\"Heb.12.1\"></r>؛ <g>ὁ λόγος τ. κυρίου</g> (قارن <r v=\"Ps.147.4\"></r>: <g>ἕως τάχους δραμεῖται ὁ λ. αὐτοῦ</g>)، <r v=\"2Thess.3.1\"></r> (قارن <g>εἰς-</g>، <g>κατα-</g>، <g>περι-</g>، <g>προ-</g>، <g>προσ-</g>، <g>συν-</g>، <g>ἐπι-συν-</g>، <g>ὑπο-τρέχω</g>).†</s>","en":"<f><o>τρέχω </o></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7323\">רוּץ</h> ;] </e> </et> <s><b>to run</b>: <r v=\"Mark.5.6\"></r>, <r v=\"John.20.2\"></r>, <r v=\"John.20.4\"></r>, <r v=\"1Cor.9.24\"></r>, <r v=\"1Cor.9.26\"></r>; c. inf., <r v=\"Matt.28.8\"></r>; seq. <g>ἐπί</g>, <r v=\"Luke.24.12\"></r> [T |[WH]| R, mg., om.]; <g>εἰς</g>, <r v=\"Rev.9.9\"></r>; ptcp., <g>δραμών</g>, c. indic., <r v=\"Matt.27.48\"></r>, <r v=\"Mark.15.36\"></r>, <r v=\"Luke.15.20\"></r>. Metaph., from runners in a race, of swiftness or of effort to attain an end: <r v=\"Rom.9.16\"></r>, <r v=\"Gal.2.2\"></r> <r v=\"Gal.5.7\"></r>, <r v=\"Phil.2.16\"></r>; <g>τ. ἀγῶνα</g> (Hdt., Eur., al.), <r v=\"Heb.12.1\"></r>; <g>ὁ λόγος τ. κυρίου</g> (cf. <r v=\"Ps.147.4\"></r>), <g>ἕως τάχους δραμεῖται ὁ λ. αὐτοῦ</g>), <r v=\"2Thess.3.1\"></r> (cf. <g>εἰς-</g>, <g>κατα-</g>, <g>περι-</g>, <g>προ-</g>, <g>προσ-</g>, <g>συν-</g>, <g>ἐπι-συν-</g>, <g>ὑπο-τρέχω</g>).†</s>"},"G5199":{"l":"ὑγιής","o":11,"ar":"<f><o>ὑγιής</o>، <g>-ές</g>، حالة النصب: <g>ὑγιῆ</g>، </f> <s><b>صحيح، معافى، سليم</b>: <r v=\"Matt.12.13\"></r> <r v=\"Matt.15.31\"></r>، <r v=\"John.5.4\"></r>، <r v=\"John.5.6\"></r>، <r v=\"John.5.9\"></r>، <r v=\"John.5.11\"></r>، <r v=\"John.5.14\"></r>، <r v=\"John.5.15\"></r> <r v=\"John.7.23\"></r>، <r v=\"Acts.4.10\"></r>؛ يليه <g>ἀπό</g>، <r v=\"Mark.5.34\"></r>؛ مجازيًا عن الكلام والآراء ونحوها، <g>λόγος</g>، <r v=\"Titus.2.8\"></r>.†</s>","en":"<f><o>ὑγιής</o>, <g>-ές</g>, acc., <g>ὑγιῆ</g> (Attic usually <g>-ιᾶ</g>), </f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2416\">חַי</h>, etc. ;]</e> </et> <s><b>sound, whole, healthy</b>: <r v=\"Matt.12.13\"></r> <r v=\"Matt.15.31\"></r>, <r v=\"John.5.4\"></r>, <r v=\"John.5.6\"></r>, <r v=\"John.5.9\"></r>, <r v=\"John.5.11\"></r>, <r v=\"John.5.14\"></r>, <r v=\"John.5.15\"></r> <r v=\"John.7.23\"></r>, <r v=\"Acts.4.10\"></r>; seq. <g>ἀπό</g>, <r v=\"Mark.5.34\"></r>; of words, opinions, etc. (as in cl.), metaph., <g>λόγος</g>, <r v=\"Titus.2.8\"></r>.†</s>"},"G5106":{"l":"τοίνυν","o":3,"ar":"<f><o>τοί-νυν </o></f> أداة استنتاج، <s><b>إذًا، لذلك</b>: كما في الكلاسيكية بعد الكلمة الأولى من الجملة، <r v=\"1Cor.9.26\"></r>؛ وبحسب الاستعمال المتأخر في أول الجملة، <r v=\"Luke.20.25\"></r>، <r v=\"Heb.13.13\"></r>.†</s>","en":"<f><o>τοί-νυν </o></f> an inferential particle, <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.3.10\"></r> <r v=\"Isa.5.13\"></r> <r v=\"Isa.27.4\"></r>, <r v=\"Wis.1.11\"></r> <r v=\"Wis.8.9\"></r>, a1. * ;] </e> </et> <s><b>accordingly, therefore</b>: as in cl., after the first word in a sentence, <r v=\"1Cor.9.26\"></r>; acc to later usage, at the beginning, <r v=\"Luke.20.25\"></r>, <r v=\"Heb.13.13\"></r>.†</s>"},"G5186":{"l":"τυφλόω","o":3,"ar":"<f><o>τυφλόω</o>، <g>-ῶ</g></f> <s><b>أعمى، جعله أعمى</b>: مجازيًا، <r v=\"John.12.40\"></r> (وفي السبعينية <g>καμμύω</g>)، <r v=\"2Cor.4.4\"></r>، <r v=\"1John.2.11\"></r>.†</s>","en":"<f><o>τυφλόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>τυφλός</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Isa.42.19\"></r> (<h n=\"H5787\">עִוֵּר</h>), <r v=\"Tob.7.7\"></r> <h>א</h>, <r v=\"Wis.2.21\"></r> <h>א</h> * ;] </e> </et> <s><b>to blind, make blind</b>: metaph., <r v=\"John.12.40\"></r> (LXX, <g>καμμύω</g>), <r v=\"2Cor.4.4\"></r>, <r v=\"1John.2.11\"></r>.†</s>"},"G5112":{"l":"τολμηρῶς","o":1,"ar":"<f>* <o>τολμηρῶς </o></f> ظرف، <s><b>بجرأة</b>: صيغة التفضيل <g>-ότερως</g>، <r v=\"Rom.15.15\"></r>.†</s>","en":"<f>* <o>τολμηρῶς </o></f> adv., <et> <e t=\"derivation\">(&lt; <g>τολμηρός</g>, <b>bold, daring</b>), </e> </et> <s><b>boldly</b>: compar., <g>-ότερως</g> (T, Rec. <g>-ότερον</g>), <r v=\"Rom.15.15\"></r>.†</s>"},"G5129":{"l":"οὗτος","o":1387,"ar":"<f><o>οὗτος</o>، <g>αὕτη, τοῦτο</g>، حالة الجر: <g>τούτου, ταύτης, τούτου</g>،</f> ضمير إشارة (علاقته بـ <g>ἐκεῖνος</g> كعلاقة <l>hic</l> بـ <l>ille</l>)، <s><b>هذا</b>؛ <s n=\"1.\">اسمًا: <b>هذا</b>، <b>هو</b>؛ <s n=\"(a)\">مطلقًا: <r v=\"Matt.3.17\"></r>، <r v=\"Mark.9.7\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"Luke.7.45\"></r>، <r v=\"John.1.15\"></r>، <r v=\"Acts.2.15\"></r>، وفي مواضع أخرى؛ للتعبير عن الازدراء: <r v=\"Matt.13.55\"></r>، <r v=\"Matt.13.56\"></r>، <r v=\"Mark.6.2\"></r>، <r v=\"Mark.6.3\"></r>، <r v=\"John.6.42\"></r>، وفي مواضع أخرى؛ <g>εἰς τοῦτο</g>: <r v=\"Mark.1.38\"></r>، <r v=\"Rom.14.9\"></r>؛ <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>؛ قارن <r v=\"John.5.1\"></r>)، <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">للإعادة (يشير إلى ما سبق): <r v=\"Matt.5.19\"></r>، <r v=\"Mark.3.35\"></r>، <r v=\"Luke.9.48\"></r>، <r v=\"John.6.46\"></r>، <r v=\"Rom.7.10\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">للاستباق (يشير إلى ما يلي): يليه <g>ἵνα</g>: <r v=\"Luke.1.43\"></r>، <r v=\"John.3.19\"></r> (وكثيرًا) <r v=\"John.15.8\"></r>، <r v=\"Rom.14.9\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>: <r v=\"Luke.10.11\"></r>، <r v=\"John.9.30\"></r>، <r v=\"Acts.24.14\"></r>، <r v=\"Rom.2.3\"></r>، وفي مواضع أخرى؛ <g>ὅπως</g>: <r v=\"Rom.9.17\"></r>؛ <g>ἐάν</g>: <r v=\"John.13.35\"></r>؛</s> <s n=\"(d)\">تعابير خاصة: <g>τοῦτο μὲν . . . τ. δέ</g>: <b>من جهة ... ومن جهة أخرى</b>، <r v=\"Heb.10.33\"></r>؛ <g>καὶ τοῦτο</g> (<g>τοῦτον</g>، <g>ταῦτα</g>): <b>وذلك أيضًا</b> (<b>وإياه أيضًا</b>)، <r v=\"Rom.13.11\"></r>، <r v=\"1Cor.2.2\"></r>، <r v=\"Heb.11.12\"></r>؛ <g>τοῦτ’ ἐστιν</g>: <b>أي</b>، <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">صفةً مع الاسم؛ <s n=\"(a)\">مع أداة التعريف: <s n=\"(α)\">قبل الأداة: <r v=\"Matt.12.32\"></r>، <r v=\"Mark.9.29\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"John.4.15\"></r>، <r v=\"Rom.11.24\"></r>، <r v=\"Rev.19.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(β)\">بعد الاسم: <r v=\"Matt.3.9\"></r>، <r v=\"Mark.12.16\"></r>، <r v=\"Luke.11.31\"></r>، <r v=\"John.4.13\"></r>، <r v=\"Acts.6.13\"></r>، <r v=\"Rom.15.28\"></r>، <r v=\"1Cor.1.20\"></r>، <r v=\"Rev.2.24\"></r>، وفي مواضع أخرى؛</s> </s> <s n=\"(b)\">مع اسم بدون أداة التعريف (بقوة الخبر): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>، <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>، <r v=\"2Cor.13.1\"></r>.</s> </s> </s>","en":"<f><o>οὗτος</o>, <g>αὕτη, τοῦτο</g>, gen., <g>τούτου, ταύτης, τούτου</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2088\">זֶה</h>, <h n=\"H2063\">זֹאת</h>;]</e> </et> demonstr. pron. (related to <g>ἐκεῖνος</g> as <l>hic</l> to <l>ille</l>), <s><b>this</b>; <s n=\"1.\">as subst., <b>this one</b>, <b>he</b>; <s n=\"(a)\">absol.: <r v=\"Matt.3.17\"></r>, <r v=\"Mark.9.7\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"Luke.7.45\"></r>, <r v=\"John.1.15\"></r>, <r v=\"Acts.2.15\"></r>, al.; expressing contempt (cl.), <r v=\"Matt.13.55\"></r>, <r v=\"Matt.13.56\"></r>, <r v=\"Mark.6.2\"></r>, <r v=\"Mark.6.3\"></r>, <r v=\"John.6.42\"></r>, al.; <g>εἰς τοῦτο</g>, <r v=\"Mark.1.38\"></r>, <r v=\"Rom.14.9\"></r>; <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>; V. Westc. on <r v=\"John.5.1\"></r>), <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>, al.;</s> <s n=\"(b)\">epanaleptic (referring to what precedes): <r v=\"Matt.5.19\"></r>, <r v=\"Mark.3.35\"></r>, <r v=\"Luke.9.48\"></r>, <r v=\"John.6.46\"></r>, <r v=\"Rom.7.10\"></r>, al.;</s> <s n=\"(c)\">proleptic (referring to what follows): seq. <g>ἵνα</g> (Bl., § 69, 6), <r v=\"Luke.1.43\"></r>, <r v=\"John.3.19\"></r> (and freq.) <r v=\"John.15.8\"></r>, <r v=\"Rom.14.9\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Luke.10.11\"></r>, <r v=\"John.9.30\"></r>, <r v=\"Acts.24.14\"></r>, <r v=\"Rom.2.3\"></r>, al.; <g>ὅπως</g>, <r v=\"Rom.9.17\"></r>; <g>ἐάν</g>, <r v=\"John.13.35\"></r>;</s> <s n=\"(d)\">special idioms: <g>τοῦτο μὲν . . . τ. δέ</g> (cl), <b>partly . . . partly</b>, <r v=\"Heb.10.33\"></r>; <g>καὶ τοῦτο</g> (<g>τοῦτον</g>, <g>ταῦτα</g>), <b>and that</b> (<b>him</b>) <b>too</b>, <r v=\"Rom.13.11\"></r>, <r v=\"1Cor.2.2\"></r>, <r v=\"Heb.11.12\"></r>; <g>τοῦτ’ ἐστιν</g>, <b>that is to say</b>, <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">As adj., c. subst.; <s n=\"(a)\">c. art. <s n=\"(α)\">before the art.: <r v=\"Matt.12.32\"></r>, <r v=\"Mark.9.29\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"John.4.15\"></r>, <r v=\"Rom.11.24\"></r>, <r v=\"Rev.19.9\"></r>, al.;</s> <s n=\"(β)\">after the noun: <r v=\"Matt.3.9\"></r>, <r v=\"Mark.12.16\"></r>, <r v=\"Luke.11.31\"></r>, <r v=\"John.4.13\"></r>, <r v=\"Acts.6.13\"></r>, <r v=\"Rom.15.28\"></r>, <r v=\"1Cor.1.20\"></r>, <r v=\"Rev.2.24\"></r>, al.;</s> </s> <s n=\"(b)\">c. subst. anarth. (with predicative force; Bl., § 49, 4): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>, <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>, <r v=\"2Cor.13.1\"></r>.</s> </s> </s>"},"G5118":{"l":"τοσοῦτος","o":20,"ar":"<f><o>τοσοῦτος</o>، <g>-αύτη, -οῦτο</g></f> <s>(<r v=\"Heb.7.22\"></r>) و(في غير ذلك) <g>-οῦτον</g>، مقابِل <g>ὅσος</g>، للكمية والحجم والعدد: <b>عظيم هكذا، بهذا المقدار</b>، وفي الجمع: <b>بهذا العدد</b>: <r v=\"Matt.8.10\"></r>، <r v=\"Luke.7.9\"></r>، <r v=\"Heb.12.1\"></r>، <r v=\"Rev.18.7\"></r>، <r v=\"Rev.18.16\"></r>؛ عن الزمن: <b>طويل هكذا</b>، <g>χρόνος</g>، <r v=\"John.14.9\"></r>، <r v=\"Heb.4.7\"></r>؛ وفي الجمع: <r v=\"Luke.15.29\"></r> (<g>ἔτη</g>)، <r v=\"John.12.37\"></r> <r v=\"John.21.11\"></r>، <r v=\"1Cor.14.10\"></r>؛ يليه <g>ὥστε</g>، <r v=\"Matt.15.33\"></r>؛ مطلقًا: في الجمع: <r v=\"John.6.9\"></r>، <r v=\"Gal.3.4\"></r>؛ عن الثمن: <g>τοσούτου</g>، <r v=\"Acts.5.8\"></r>؛ وفي القابل: <g>τοσούτῳ κρείττων</g>، <r v=\"Heb.1.4\"></r>؛ <g>τ. μᾶλλον ὅσῳ</g>، <r v=\"Heb.10.25\"></r>؛ <g>καθ’ ὅσον . . . κατὰ τ.</g>، <r v=\"Heb.7.22\"></r>.†</s>","en":"<f><o>τοσοῦτος</o>, <g>-αύτη, -οῦτο</g></f> <s>(<r v=\"Heb.7.22\"></r>) and (elsewhere, as usually in Attic) <g>-οῦτον</g>, correlat. of <g>ὅσος</g>, of quantity, size, number, <b>so great, so much</b>, pl., <b>so many</b>: <r v=\"Matt.8.10\"></r>, <r v=\"Luke.7.9\"></r>, <r v=\"Heb.12.1\"></r>, <r v=\"Rev.18.7\"></r>, <r v=\"Rev.18.16\"></r>; of time, <b>so long</b>, <g>χρόνος</g>, <r v=\"John.14.9\"></r>, <r v=\"Heb.4.7\"></r>; pl., <r v=\"Luke.15.29\"></r> (<g>ἔτη</g>), <r v=\"John.12.37\"></r> <r v=\"John.21.11\"></r>, <r v=\"1Cor.14.10\"></r>; seq. <g>ὥστε</g>, <r v=\"Matt.15.33\"></r>; absol.: pl., <r v=\"John.6.9\"></r>, <r v=\"Gal.3.4\"></r>; of price, <g>τοσούτου</g>, <r v=\"Acts.5.8\"></r>; dat., <g>τοσούτῳ κρείττων</g>, <r v=\"Heb.1.4\"></r>; <g>τ. μᾶλλον ὅσῳ</g>, <r v=\"Heb.10.25\"></r>; <g>καθ’ ὅσον . . . κατὰ τ.</g>, <r v=\"Heb.7.22\"></r>.†</s>"},"G5137":{"l":"τράχηλος","o":7,"ar":"<f><o>τράχηλος</o>، <g>-ου, ὁ </g> </f> <s><b>العنق، الرقبة</b>: <r v=\"Matt.18.6\"></r>، <r v=\"Mark.9.42\"></r>، <r v=\"Luke.17.2\"></r>؛ <g>ἐπιπεσεῖν ἐπὶ τὸν τ.</g>: عانق (<r v=\"Gen.46.29\"></r>)، <r v=\"Luke.15.20\"></r>، <r v=\"Acts.20.37\"></r>. ومجازيًا: <g>ὑποθεῖναι τὸν ἑαυτοῦ τ.</g>، <r v=\"Rom.16.4\"></r>؛ <g>ἐπιθεῖναι ζυγὸν ἐπὶ τὸν τ.</g>، <r v=\"Acts.15.10\"></r>.†</s>","en":"<f><o>τράχηλος</o>, <g>-ου, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6676\">צַוַּאר</h>, also for<h n=\"H6203\">עֹרֶף</h>, etc. ;]</e> </et> <s><b>the neck</b>: <r v=\"Matt.18.6\"></r>, <r v=\"Mark.9.42\"></r>, <r v=\"Luke.17.2\"></r>; <g>ἐπιπεσεῖν ἐπὶ τὸν τ.</g>, to embrace (<r v=\"Gen.46.29\"></r>), <r v=\"Luke.15.20\"></r>, <r v=\"Acts.20.37\"></r>. Metaph., <g>ὑποθεῖναι τὸν ἑαυτοῦ τ.</g> (for similar phrase in <g>π.</g>, v. Zorell, s.v.), <r v=\"Rom.16.4\"></r>; <g>ἐπιθεῖναι ζυγὸν ἐπὶ τὸν τ.</g>, <r v=\"Acts.15.10\"></r>.†</s>"},"G5173":{"l":"Τρυφῶσα","o":1,"ar":"<f><o>Τρυφῶσα</o>، <g>-ης, ἡ, ς, ἡ </g> </f> <s><b>تريفوسا</b>: <r v=\"Rom.16.12\"></r>.†</s>","en":"<f><o>Τρυφῶσα</o>, <g>-ης, ἡ, ς, ἡ </g></f> <s><b>Tryphosa</b>: <r v=\"Rom.16.12\"></r> (v. Lft., <i>Phl.</i>, 175 f.).†</s>"},"G5162":{"l":"τροφός","o":1,"ar":"<f><o>τροφός</o>، <g>-οῦ, ἡ</g></f> <s><b>مرضعة</b>: <r v=\"1Thess.2.7\"></r>.†</s>","en":"<f><o>τροφός</o>, <g>-οῦ, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>τρέφω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Gen.35.8\"></r>, <r v=\"2Kgs.11.2\"></r>, <r v=\"2Chr.22.11\"></r> <r v=\"Isa.49.23\"></r> (<h n=\"H3243\">מֵינֶקֶת</h>) * ;] </e> </et> <s><b>a nurse</b>: <r v=\"1Thess.2.7\"></r>.†</s>"},"G5128":{"l":"οὗτος","o":1387,"ar":"<f><o>οὗτος</o>، <g>αὕτη, τοῦτο</g>، حالة الجر <g>τούτου, ταύτης, τούτου</g>،</f> ضمير إشارة (نسبته إلى <g>ἐκεῖνος</g> كنسبة <l>hic</l> إلى <l>ille</l>)، <s><b>هذا</b>؛ <s n=\"1.\">بمعنى الاسم: <b>هذا</b>، <b>هو</b>؛ <s n=\"(a)\">مطلقًا: <r v=\"Matt.3.17\"></r>، <r v=\"Mark.9.7\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"Luke.7.45\"></r>، <r v=\"John.1.15\"></r>، <r v=\"Acts.2.15\"></r>، وفي مواضع أخرى؛ للتعبير عن الازدراء، <r v=\"Matt.13.55\"></r>، <r v=\"Matt.13.56\"></r>، <r v=\"Mark.6.2\"></r>، <r v=\"Mark.6.3\"></r>، <r v=\"John.6.42\"></r>، وفي مواضع أخرى؛ <g>εἰς τοῦτο</g>، <r v=\"Mark.1.38\"></r>، <r v=\"Rom.14.9\"></r>؛ <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>؛ قارن <r v=\"John.5.1\"></r>)، <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">استرجاعيًّا (يشير إلى ما سبق): <r v=\"Matt.5.19\"></r>، <r v=\"Mark.3.35\"></r>، <r v=\"Luke.9.48\"></r>، <r v=\"John.6.46\"></r>، <r v=\"Rom.7.10\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">استباقيًّا (يشير إلى ما يلي): يليه <g>ἵνα</g>، <r v=\"Luke.1.43\"></r>، <r v=\"John.3.19\"></r> (وكثيرًا) <r v=\"John.15.8\"></r>، <r v=\"Rom.14.9\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>، <r v=\"Luke.10.11\"></r>، <r v=\"John.9.30\"></r>، <r v=\"Acts.24.14\"></r>، <r v=\"Rom.2.3\"></r>، وفي مواضع أخرى؛ <g>ὅπως</g>، <r v=\"Rom.9.17\"></r>؛ <g>ἐάν</g>، <r v=\"John.13.35\"></r>؛</s> <s n=\"(d)\">تعبيرات خاصة: <g>τοῦτο μὲν . . . τ. δέ</g>، <b>من جهة . . . ومن جهة أخرى</b>، <r v=\"Heb.10.33\"></r>؛ <g>καὶ τοῦτο</g> (<g>τοῦτον</g>، <g>ταῦτα</g>)، <b>وذلك</b> (<b>وإياه</b>) <b>أيضًا</b>، <r v=\"Rom.13.11\"></r>، <r v=\"1Cor.2.2\"></r>، <r v=\"Heb.11.12\"></r>؛ <g>τοῦτ’ ἐστιν</g>، <b>أي</b>، <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">صفةً، مع اسم؛ <s n=\"(a)\">مع أداة التعريف <s n=\"(α)\">قبل الأداة: <r v=\"Matt.12.32\"></r>، <r v=\"Mark.9.29\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"John.4.15\"></r>، <r v=\"Rom.11.24\"></r>، <r v=\"Rev.19.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(β)\">بعد الاسم: <r v=\"Matt.3.9\"></r>، <r v=\"Mark.12.16\"></r>، <r v=\"Luke.11.31\"></r>، <r v=\"John.4.13\"></r>، <r v=\"Acts.6.13\"></r>، <r v=\"Rom.15.28\"></r>، <r v=\"1Cor.1.20\"></r>، <r v=\"Rev.2.24\"></r>، وفي مواضع أخرى؛</s> </s> <s n=\"(b)\">مع اسم بدون أداة التعريف (بقوة الخبر): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>، <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>، <r v=\"2Cor.13.1\"></r>.</s> </s> </s>","en":"<f><o>οὗτος</o>, <g>αὕτη, τοῦτο</g>, gen., <g>τούτου, ταύτης, τούτου</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2088\">זֶה</h>, <h n=\"H2063\">זֹאת</h>;]</e> </et> demonstr. pron. (related to <g>ἐκεῖνος</g> as <l>hic</l> to <l>ille</l>), <s><b>this</b>; <s n=\"1.\">as subst., <b>this one</b>, <b>he</b>; <s n=\"(a)\">absol.: <r v=\"Matt.3.17\"></r>, <r v=\"Mark.9.7\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"Luke.7.45\"></r>, <r v=\"John.1.15\"></r>, <r v=\"Acts.2.15\"></r>, al.; expressing contempt (cl.), <r v=\"Matt.13.55\"></r>, <r v=\"Matt.13.56\"></r>, <r v=\"Mark.6.2\"></r>, <r v=\"Mark.6.3\"></r>, <r v=\"John.6.42\"></r>, al.; <g>εἰς τοῦτο</g>, <r v=\"Mark.1.38\"></r>, <r v=\"Rom.14.9\"></r>; <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>; V. Westc. on <r v=\"John.5.1\"></r>), <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>, al.;</s> <s n=\"(b)\">epanaleptic (referring to what precedes): <r v=\"Matt.5.19\"></r>, <r v=\"Mark.3.35\"></r>, <r v=\"Luke.9.48\"></r>, <r v=\"John.6.46\"></r>, <r v=\"Rom.7.10\"></r>, al.;</s> <s n=\"(c)\">proleptic (referring to what follows): seq. <g>ἵνα</g> (Bl., § 69, 6), <r v=\"Luke.1.43\"></r>, <r v=\"John.3.19\"></r> (and freq.) <r v=\"John.15.8\"></r>, <r v=\"Rom.14.9\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Luke.10.11\"></r>, <r v=\"John.9.30\"></r>, <r v=\"Acts.24.14\"></r>, <r v=\"Rom.2.3\"></r>, al.; <g>ὅπως</g>, <r v=\"Rom.9.17\"></r>; <g>ἐάν</g>, <r v=\"John.13.35\"></r>;</s> <s n=\"(d)\">special idioms: <g>τοῦτο μὲν . . . τ. δέ</g> (cl), <b>partly . . . partly</b>, <r v=\"Heb.10.33\"></r>; <g>καὶ τοῦτο</g> (<g>τοῦτον</g>, <g>ταῦτα</g>), <b>and that</b> (<b>him</b>) <b>too</b>, <r v=\"Rom.13.11\"></r>, <r v=\"1Cor.2.2\"></r>, <r v=\"Heb.11.12\"></r>; <g>τοῦτ’ ἐστιν</g>, <b>that is to say</b>, <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">As adj., c. subst.; <s n=\"(a)\">c. art. <s n=\"(α)\">before the art.: <r v=\"Matt.12.32\"></r>, <r v=\"Mark.9.29\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"John.4.15\"></r>, <r v=\"Rom.11.24\"></r>, <r v=\"Rev.19.9\"></r>, al.;</s> <s n=\"(β)\">after the noun: <r v=\"Matt.3.9\"></r>, <r v=\"Mark.12.16\"></r>, <r v=\"Luke.11.31\"></r>, <r v=\"John.4.13\"></r>, <r v=\"Acts.6.13\"></r>, <r v=\"Rom.15.28\"></r>, <r v=\"1Cor.1.20\"></r>, <r v=\"Rev.2.24\"></r>, al.;</s> </s> <s n=\"(b)\">c. subst. anarth. (with predicative force; Bl., § 49, 4): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>, <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>, <r v=\"2Cor.13.1\"></r>.</s> </s> </s>"},"G5179":{"l":"τύπος","o":null,"ar":"<f><o>τύπος</o>، <g>-ου, ὁ</g></f> <s n=\"1.\"><b>أثر</b> الضربة: <g>τῶν ἥλων</g>، <r v=\"John.20.25\"></r>. </s> <s n=\"2.\"><b>طبعة، أثر مطبوع</b>، <b>الختم</b> الذي يتركه القالب؛ ومن ثمّ <b>تمثال، صورة</b>: <r v=\"Acts.7.43\"></r> <i>(السبعينية)</i>. </s> <s n=\"3.\"><b>صورة، شكل</b>: <r v=\"Rom.6.17\"></r>؛ عن مضمون الرسالة أو فحواها (<r v=\"3Macc.3.30\"></r>)، <r v=\"Acts.23.25\"></r>. </s> <s n=\"4.\"><b>مثال، نموذج</b>: <r v=\"Acts.7.44\"></r>، <r v=\"Heb.8.6\"></r>؛ بالمعنى الأخلاقي، <r v=\"Phil.3.17\"></r>، <r v=\"1Thess.1.7\"></r>، <r v=\"2Thess.3.9\"></r>، <r v=\"1Tim.4.12\"></r>، <r v=\"Titus.2.7\"></r>، <r v=\"1Pet.5.3\"></r>؛ بالمعنى العقائدي: <b>رمز</b>، <r v=\"Rom.5.14\"></r>.† </s>","en":"<f><o>τύπος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>τύπτω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.25.39\"></r> (40) (<h n=\"H8403\">תַּבְנִית</h>), <r v=\"Amos.5.26\"></r> (<h n=\"H6754\">צֶלֶם</h>), <r v=\"3Macc.3.30\"></r>, <r v=\"4Macc.6.19\"></r> * ;]</e> </et> <s n=\"1.\">the <b>mark</b> of a blow: <g>τῶν ἥλων</g>, <r v=\"John.20.25\"></r>. </s> <s n=\"2.\">An <b>impression, impress</b>, the <b>stamp</b> made by a die; hence, <b>a figure, image</b>: <r v=\"Acts.7.43\"></r> <i>(LXX)</i>. </s> <s n=\"3.\"><b>form</b> (Plat.): <r v=\"Rom.6.17\"></r>; the sense or substance of a letter (<r v=\"3Macc.3.30\"></r>), <r v=\"Acts.23.25\"></r>. </s> <s n=\"4.\"><b>an example, pattern</b>: <r v=\"Acts.7.44\"></r>, <r v=\"Heb.8.6\"></r>; in ethical sense, <r v=\"Phil.3.17\"></r>, <r v=\"1Thess.1.7\"></r>, <r v=\"2Thess.3.9\"></r>, <r v=\"1Tim.4.12\"></r>, <r v=\"Titus.2.7\"></r>, <r v=\"1Pet.5.3\"></r>; in doctrinal sense, <b>type</b> (v. <i>ICC</i>, in l.), <r v=\"Rom.5.14\"></r>.† </s> <sy><i>SYN.</i>: v.s. <g>ὑποτύπωσις</g> </sy>"},"G5197":{"l":"ὑβριστής","o":2,"ar":"<f><o>ὑβριστής</o>، <g>-οῦ, ὁ</g></f> <s><b>رجل عنيف، متجبّر</b>: <r v=\"Rom.1.20\"></r>، <r v=\"1Tim.1.13\"></r> (وفي الترجمات الإنجليزية: <b>مُفترٍ</b>).† </s>","en":"<f><o>ὑβριστής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>ὑβρίζω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1343\">גֵּאֶה</h> ;] </e> </et> <s><b>a violent, insolent man</b>: <r v=\"Rom.1.20\"></r>, <r v=\"1Tim.1.13\"></r> (EV, <b>injurious</b>).† </s> <sy><i>SYN.</i>: <g>ἀλαζών</g>, <g>ὑπερήφανος</g>, v. Tr., <i>Syn.</i>, § xxix.</sy>"},"G5161":{"l":"Τρόφιμος","o":3,"ar":"<f><o>Τρόφιμος</o>، <g>-ου, ὁ </g></f> <s><b>تروفيمس</b>: <r v=\"Acts.20.4\"></r>، <r v=\"Acts.21.29\"></r>، <r v=\"2Tim.4.20\"></r>.†</s>","en":"<f><o>Τρόφιμος</o>, <g>-ου, ὁ </g></f> <s><b>Trophimus</b>: <r v=\"Acts.20.4\"></r> <r v=\"Acts.21.29\"></r>, <r v=\"2Tim.4.20\"></r>.†</s>"},"G5105":{"l":"τοιγαροῦν","o":2,"ar":"<f><o>τοι-γαρ-οῦν </o></f> أداة استنتاج، <s><b>لذلك إذًا، فإذًا</b>: <r v=\"1Thess.4.8\"></r>، <r v=\"Heb.12.1\"></r>.†</s>","en":"<f><o>τοι-γαρ-οῦν </o></f> an inferential particle, <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.22.10\"></r> <r v=\"Job.24.22\"></r> (<h n=\"H????\">עַל־כֵּך</h>), <r v=\"Sir.41.16\"></r>, al. ;] </e> </et> <s><b>wherefore then, so therefore</b>: <r v=\"1Thess.4.8\"></r>, <r v=\"Heb.12.1\"></r> (Hdt., Plat., al.).†</s>"},"G5142":{"l":"τρέφω","o":9,"ar":"<f><o>τρέφω </o></f> <s n=\"1.\"><b>أنمى، ربّى، نشّأ</b> (قارن <r v=\"1Macc.3.33\"></r> <r v=\"1Macc.11.39\"></r>): <r v=\"Luke.4.16\"></r> </s> <s n=\"2.\"><b>غذّى، أطعم، عال</b>: <r v=\"Matt.6.26\"></r> <r v=\"Matt.25.37\"></r>، <r v=\"Luke.12.24\"></r>، <r v=\"Acts.12.20\"></r>، <r v=\"Rev.12.6\"></r>، <r v=\"Rev.12.14\"></r>؛ عن الأم، <b>أرضع</b>، <r v=\"Luke.23.29\"></r>؛ عن الحيوانات، <b>سمّن</b> (<r v=\"Jer.46.21\"></r>)، ومجازيًا، <r v=\"Jas.5.5\"></r> (قارن <g>ἀνα-</g>، <g>ἐκ-</g>، <g>ἐν-τρέφω</g>).†</s>","en":"<f><o>τρέφω </o></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2421\">חָיָה</h> hi., <h n=\"H1431\">גָּדַל</h> pi., <h n=\"H398\">אָכַל</h> hi., etc. ;]</e> </et> <s n=\"1.\"><b>to make to grow, bring up, rear</b> (cl.; <r v=\"1Macc.3.33\"></r> <r v=\"1Macc.11.39\"></r>): <r v=\"Luke.4.16\"></r> (T, WH, mg., <g>ἀνατ-</g>) </s> <s n=\"2.\"><b>to nourish, feed</b>: <r v=\"Matt.6.26\"></r> <r v=\"Matt.25.37\"></r>, <r v=\"Luke.12.24\"></r>, <r v=\"Acts.12.20\"></r>, <r v=\"Rev.12.6\"></r>, <r v=\"Rev.12.14\"></r>; of a mother, <b>to give suck</b>, <r v=\"Luke.23.29\"></r>; of animals, <b>to fatten</b> (<r v=\"Jer.46.21\"></r>), fig., <r v=\"Jas.5.5\"></r> (cf. <g>ἀνα-</g>, <g>ἐκ-</g>, <g>ἐν-τρέφω</g>).†</s>"},"G5166":{"l":"τρυγάω","o":3,"ar":"<f><o>τρυγάω</o>، <g>-ῶ </g></f> <s><b>قطف، جنى</b>: مع المنصوب، </s> <s n=\"(a)\">للثمر، <r v=\"Luke.6.44\"></r>، <r v=\"Rev.14.18\"></r>؛ </s> <s n=\"(b)\">لما يُجنى منه الثمر، <r v=\"Rev.14.19\"></r>.†</s>","en":"<f><o>τρυγάω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H7114\">קָצַר</h>, <h n=\"H1219\">בָּצַר</h>, etc. ;]</e> </et> <s><b>to gather in</b>: c. acc, </s> <s n=\"(a)\">of the fruit, <r v=\"Luke.6.44\"></r>, <r v=\"Rev.14.18\"></r>; </s> <s n=\"(b)\">of that from which it is gathered, <r v=\"Rev.14.19\"></r>.†</s>"},"G5163":{"l":"τροχιά","o":1,"ar":"<f><o>τροχιά</o>، <g>-ᾶς, ἡ</g></f> <s><b>أثر العجلة</b>، ومن ثَمّ <b>أثر، مسلك، سبيل</b>: مجازيًا، <r v=\"Heb.12.13\"></r> <i>(السبعينية)</i> †</s>","en":"<f><o>τροχιά</o>, <g>-ᾶς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>τροχός</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.2.15\"></r> <r v=\"Prov.4.11\"></r>, <r v=\"Prov.4.26\"></r>, <r v=\"Prov.4.27\"></r> <r v=\"Prov.5.6\"></r>, <r v=\"Prov.5.21\"></r> (<h n=\"H4570\">מַעְגָּל</h>), <r v=\"Ezek.27.19\"></r> A* ;] </e> </et> <s><b>the track of a wheel</b>, hence, <b>a track, path</b>: fig., <r v=\"Heb.12.13\"></r> <i>(LXX)</i> †</s>"},"G5155":{"l":"τρίχινος","o":1,"ar":"<f><o>τρίχινος</o>، <g>-η, -ον</g></f> <s>مصنوع من الشَّعر: <g>στόκος</g>، <r v=\"Rev.6.12\"></r>.†</s>","en":"<f><o>τρίχινος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>θρίξ</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Zech.13.4\"></r> (<h n=\"H8181\">שֵׂעָר</h>), <r v=\"Exod.26.7\"></r> * ;] </e> </et> <s>of hair: <g>στόκος</g>, <r v=\"Rev.6.12\"></r> (Xen., Plat., al.).†</s>"},"G5160":{"l":"τροφή","o":16,"ar":"<f><o>τροφή</o>، <g>-ῆς, ἡ</g></f> <s><b>غذاء، طعام</b>: <r v=\"Matt.3.4\"></r> <r v=\"Matt.6.25\"></r> <r v=\"Matt.10.10\"></r> <r v=\"Matt.24.45\"></r>، <r v=\"Luke.12.23\"></r>، <r v=\"John.4.8\"></r>، <r v=\"Acts.2.46\"></r> <r v=\"Acts.9.19\"></r> <r v=\"Acts.14.17\"></r> <r v=\"Acts.27.33\"></r>، <r v=\"Acts.27.34\"></r>، <r v=\"Acts.27.36\"></r>، <r v=\"Acts.27.38\"></r>، <r v=\"Jas.2.15\"></r>. مجازيًا: <r v=\"Heb.5.12\"></r>، <r v=\"Heb.5.14\"></r>.†</s>","en":"<f><o>τροφή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>τρέφω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H3899\">לֶחֶם</h>, <h n=\"H4202\">מָזוֹן</h>, <h n=\"H400\">אֹכֶל</h>, etc. ;] </e> </et> <s><b>nourishment, food</b>: <r v=\"Matt.3.4\"></r> <r v=\"Matt.6.25\"></r> <r v=\"Matt.10.10\"></r> <r v=\"Matt.24.45\"></r>, <r v=\"Luke.12.23\"></r>, <r v=\"John.4.8\"></r>, <r v=\"Acts.2.46\"></r> <r v=\"Acts.9.19\"></r> <r v=\"Acts.14.17\"></r> <r v=\"Acts.27.33\"></r>, <r v=\"Acts.27.34\"></r>, <r v=\"Acts.27.36\"></r>, <r v=\"Acts.27.38\"></r>, <r v=\"Jas.2.15\"></r>. Metaph.: <r v=\"Heb.5.12\"></r>, <r v=\"Heb.5.14\"></r>.†</s>"},"G5172":{"l":"τρυφή","o":2,"ar":"<f><o>τρυφή</o>، <g>-ῆς, ἡ</g></f> <s><b>نعومة، رفاهية، تنعُّم</b>: <r v=\"Luke.7.25\"></r>، <r v=\"2Pet.2.13\"></r>.†</s>","en":"<f><o>τρυφή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5727\">עָדַן</h> ;] </e> </et> <s><b>softness, daintiness, luxuriousness</b>: <r v=\"Luke.7.25\"></r>, <r v=\"2Pet.2.13\"></r>.†</s>"},"G5141":{"l":"τρέμω","o":3,"ar":"<f><o>τρέμω </o></f> <s><b>ارتعد</b>، خاصةً من الخوف: <r v=\"Mark.5.33\"></r>، <r v=\"Luke.8.47\"></r>؛ مع اسم الفاعل، <r v=\"2Pet.2.10\"></r>.†</s>","en":"<f><o>τρέμω </o></f> <s><b>to tremble</b>, esp. with fear: <r v=\"Mark.5.33\"></r>, <r v=\"Luke.8.47\"></r>; c. ptcp. (in cl more freq. c. inf.), <r v=\"2Pet.2.10\"></r>.†</s>"},"G5157":{"l":"τροπή","o":1,"ar":"<f><o>τροπή</o>، <g>-ῆς, ἡ</g></f> <s><b>تحوّل، دوران</b>: خاصةً عن دوران الأجرام السماوية، مجازيًا، <r v=\"Jas.1.17\"></r> (انظر تحت المدخل <g>ἀποσκίασμα</g>).†</s>","en":"<f><o>τροπή</o>, <g>-ῆς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>τρέπω</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.33.14\"></r>, <r v=\"Job.38.33\"></r>, <r v=\"Wis.7.18\"></r>, al. ;] </e> </et> <s><b>a turning</b>: esp. of the revolution of heavenly bodies, fig., <r v=\"Jas.1.17\"></r> (v.s. <g>ἀποσκίασμα</g>).†</s>"},"G5116":{"l":"τοπάζιον","o":1,"ar":"<f>† <o>τοπάζιον</o>، <g>-ου, τό</g></f> <s><b>ياقوت أصفر</b>: <r v=\"Rev.21.20\"></r>.†</s>","en":"<f>† <o>τοπάζιον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(and <g>τόπαζος, ὁ</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Exod.28.17\"></r> <r v=\"Exod.35.17\"></r> (<r v=\"Exod.39.10\"></r>), <r v=\"Job.28.19\"></r>, <r v=\"Ezek.28.13\"></r> (<h n=\"H6357\">פִּטְדָה</h>), <r v=\"Ps.119.127\"></r> (<h n=\"H6337\">פָּז</h>)* ;] </e> </et> <s><b>topaz</b>: <r v=\"Rev.21.20\"></r> (v. Swete, in l.).†</s>"},"G5194":{"l":"ὕαλος","o":2,"ar":"<f><o>ὕαλος</o>، <g>-ου, ὁ </g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>حجر شفّاف صافٍ</b>. </s> <s n=\"2.\"><b>زجاج</b>: <r v=\"Rev.21.18\"></r>، <r v=\"Rev.21.21\"></r>.†</s>","en":"<f><o>ὕαλος</o>, <g>-ου, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.28.17\"></r> (<h n=\"H2137\">זְכוּכִית</h>) * ;]</e> </et> <s n=\"1.\">(Hdt.) <b>a clear transparent stone</b>. </s> <s n=\"2.\">(from Plat. on) <b>glass</b>: <r v=\"Rev.21.18\"></r>, <r v=\"Rev.21.21\"></r>.†</s>"},"G5113":{"l":"τολμητής","o":1,"ar":"<f>* <o>τολμητής</o>، <g>-οῦ, ὁ </g></f> <s><b>رجل جريء، مقتحم</b>: <r v=\"2Pet.2.10\"></r>.†</s>","en":"<f>* <o>τολμητής</o>, <g>-οῦ, ὁ </g></f> <et> <e t=\"derivation\">(&lt; <g>τολμάω</g>), </e> </et> <s><b>a bold, daring man</b>: <r v=\"2Pet.2.10\"></r> (Thuc.).†</s>"},"G5123":{"l":"τουτέστι","o":null,"ar":"<f><o>τουτέστι = τοῦτ ̓ ἔστι </o></f>","en":"<f><o>τουτέστι = τοῦτ ̓ ἔστι </o></f>"},"G5125":{"l":"οὗτος","o":1387,"ar":"<f><o>οὗτος</o>، <g>αὕτη, τοῦτο</g>، حالة الجر <g>τούτου, ταύτης, τούτου</g>،</f> ضمير إشارة (علاقته بـ<g>ἐκεῖνος</g> كعلاقة <l>hic</l> بـ<l>ille</l> في اللاتينية)، <s><b>هذا</b>؛ <s n=\"1.\">بمعنى الاسم: <b>هذا الشخص</b>، <b>هو</b>؛ <s n=\"(a)\">مطلقًا: <r v=\"Matt.3.17\"></r>، <r v=\"Mark.9.7\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"Luke.7.45\"></r>، <r v=\"John.1.15\"></r>، <r v=\"Acts.2.15\"></r>، وفي مواضع أخرى؛ للتعبير عن الازدراء: <r v=\"Matt.13.55\"></r>، <r v=\"Matt.13.56\"></r>، <r v=\"Mark.6.2\"></r>، <r v=\"Mark.6.3\"></r>، <r v=\"John.6.42\"></r>، وفي مواضع أخرى؛ <g>εἰς τοῦτο</g>، <r v=\"Mark.1.38\"></r>، <r v=\"Rom.14.9\"></r>؛ <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>؛ قارن <r v=\"John.5.1\"></r>)، <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>، وفي مواضع أخرى؛</s> <s n=\"(b)\">بمعنى استرجاعي (يشير إلى ما سبق): <r v=\"Matt.5.19\"></r>، <r v=\"Mark.3.35\"></r>، <r v=\"Luke.9.48\"></r>، <r v=\"John.6.46\"></r>، <r v=\"Rom.7.10\"></r>، وفي مواضع أخرى؛</s> <s n=\"(c)\">بمعنى استباقي (يشير إلى ما يلي): يليه <g>ἵνα</g>، <r v=\"Luke.1.43\"></r>، <r v=\"John.3.19\"></r> (وكثيرًا) <r v=\"John.15.8\"></r>، <r v=\"Rom.14.9\"></r>، وفي مواضع أخرى؛ يليه <g>ὅτι</g>، <r v=\"Luke.10.11\"></r>، <r v=\"John.9.30\"></r>، <r v=\"Acts.24.14\"></r>، <r v=\"Rom.2.3\"></r>، وفي مواضع أخرى؛ <g>ὅπως</g>، <r v=\"Rom.9.17\"></r>؛ <g>ἐάν</g>، <r v=\"John.13.35\"></r>؛</s> <s n=\"(d)\">تعابير خاصة: <g>τοῦτο μὲν . . . τ. δέ</g>، <b>من جهة . . . ومن جهة أخرى</b>، <r v=\"Heb.10.33\"></r>؛ <g>καὶ τοῦτο</g> (<g>τοῦτον</g>، <g>ταῦτα</g>)، <b>وذلك</b> (<b>هو</b>) <b>أيضًا</b>، <r v=\"Rom.13.11\"></r>، <r v=\"1Cor.2.2\"></r>، <r v=\"Heb.11.12\"></r>؛ <g>τοῦτ’ ἐστιν</g>، <b>أي</b>، <b>بمعنى</b>، <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">صفةً، مع اسم؛ <s n=\"(a)\">مع أداة التعريف: <s n=\"(α)\">قبل الأداة: <r v=\"Matt.12.32\"></r>، <r v=\"Mark.9.29\"></r>، <r v=\"Luke.7.44\"></r>، <r v=\"John.4.15\"></r>، <r v=\"Rom.11.24\"></r>، <r v=\"Rev.19.9\"></r>، وفي مواضع أخرى؛</s> <s n=\"(β)\">بعد الاسم: <r v=\"Matt.3.9\"></r>، <r v=\"Mark.12.16\"></r>، <r v=\"Luke.11.31\"></r>، <r v=\"John.4.13\"></r>، <r v=\"Acts.6.13\"></r>، <r v=\"Rom.15.28\"></r>، <r v=\"1Cor.1.20\"></r>، <r v=\"Rev.2.24\"></r>، وفي مواضع أخرى؛</s> </s> <s n=\"(b)\">مع اسم بدون أداة التعريف (بقوة الخبر): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>، <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>، <r v=\"2Cor.13.1\"></r>.</s> </s> </s>","en":"<f><o>οὗτος</o>, <g>αὕτη, τοῦτο</g>, gen., <g>τούτου, ταύτης, τούτου</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2088\">זֶה</h>, <h n=\"H2063\">זֹאת</h>;]</e> </et> demonstr. pron. (related to <g>ἐκεῖνος</g> as <l>hic</l> to <l>ille</l>), <s><b>this</b>; <s n=\"1.\">as subst., <b>this one</b>, <b>he</b>; <s n=\"(a)\">absol.: <r v=\"Matt.3.17\"></r>, <r v=\"Mark.9.7\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"Luke.7.45\"></r>, <r v=\"John.1.15\"></r>, <r v=\"Acts.2.15\"></r>, al.; expressing contempt (cl.), <r v=\"Matt.13.55\"></r>, <r v=\"Matt.13.56\"></r>, <r v=\"Mark.6.2\"></r>, <r v=\"Mark.6.3\"></r>, <r v=\"John.6.42\"></r>, al.; <g>εἰς τοῦτο</g>, <r v=\"Mark.1.38\"></r>, <r v=\"Rom.14.9\"></r>; <g>μετὰ τοῦτο</g> (<g>ταῦτα</g>; V. Westc. on <r v=\"John.5.1\"></r>), <r v=\"John.2.12\"></r> <r v=\"John.11.7\"></r>, al.;</s> <s n=\"(b)\">epanaleptic (referring to what precedes): <r v=\"Matt.5.19\"></r>, <r v=\"Mark.3.35\"></r>, <r v=\"Luke.9.48\"></r>, <r v=\"John.6.46\"></r>, <r v=\"Rom.7.10\"></r>, al.;</s> <s n=\"(c)\">proleptic (referring to what follows): seq. <g>ἵνα</g> (Bl., § 69, 6), <r v=\"Luke.1.43\"></r>, <r v=\"John.3.19\"></r> (and freq.) <r v=\"John.15.8\"></r>, <r v=\"Rom.14.9\"></r>, al.; seq. <g>ὅτι</g>, <r v=\"Luke.10.11\"></r>, <r v=\"John.9.30\"></r>, <r v=\"Acts.24.14\"></r>, <r v=\"Rom.2.3\"></r>, al.; <g>ὅπως</g>, <r v=\"Rom.9.17\"></r>; <g>ἐάν</g>, <r v=\"John.13.35\"></r>;</s> <s n=\"(d)\">special idioms: <g>τοῦτο μὲν . . . τ. δέ</g> (cl), <b>partly . . . partly</b>, <r v=\"Heb.10.33\"></r>; <g>καὶ τοῦτο</g> (<g>τοῦτον</g>, <g>ταῦτα</g>), <b>and that</b> (<b>him</b>) <b>too</b>, <r v=\"Rom.13.11\"></r>, <r v=\"1Cor.2.2\"></r>, <r v=\"Heb.11.12\"></r>; <g>τοῦτ’ ἐστιν</g>, <b>that is to say</b>, <r v=\"Matt.27.46\"></r>.</s> </s> <s n=\"2.\">As adj., c. subst.; <s n=\"(a)\">c. art. <s n=\"(α)\">before the art.: <r v=\"Matt.12.32\"></r>, <r v=\"Mark.9.29\"></r>, <r v=\"Luke.7.44\"></r>, <r v=\"John.4.15\"></r>, <r v=\"Rom.11.24\"></r>, <r v=\"Rev.19.9\"></r>, al.;</s> <s n=\"(β)\">after the noun: <r v=\"Matt.3.9\"></r>, <r v=\"Mark.12.16\"></r>, <r v=\"Luke.11.31\"></r>, <r v=\"John.4.13\"></r>, <r v=\"Acts.6.13\"></r>, <r v=\"Rom.15.28\"></r>, <r v=\"1Cor.1.20\"></r>, <r v=\"Rev.2.24\"></r>, al.;</s> </s> <s n=\"(b)\">c. subst. anarth. (with predicative force; Bl., § 49, 4): <r v=\"Luke.1.36\"></r> <r v=\"Luke.2.2\"></r> <r v=\"Luke.24.21\"></r>, <r v=\"John.2.11\"></r> <r v=\"John.4.54\"></r> <r v=\"John.21.14\"></r>, <r v=\"2Cor.13.1\"></r>.</s> </s> </s>"},"G5191":{"l":"ὑακίνθινος","o":1,"ar":"<f><o>ὑακίνθινος</o>، <g>-η, -ον</g></f> <s><b>أسمانجوني، بلون الياقوت الأزرق</b> (انظر تحت مدخل <g>ὑάκινθος</g>)، ويُقصد به على الأرجح وصف الدخان الأزرق للهب الكبريتي: <r v=\"Rev.9.17\"></r>.†</s>","en":"<f><o>ὑακίνθινος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ὑάκινθος</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H8476\">תַּחַשׁ</h>, <h n=\"H8504\">תְּכֵלֶת</h> ;] </e> </et> <s><b>of hyacinth, hyacinthine</b> (v.s. <g>ὑάκινθος</g>), \"doubtless meant to describe the blue smoke of a sulphurous flame\" (Swete): <r v=\"Rev.9.17\"></r> (Hom., Eur., al.).†</s>"},"G5178":{"l":"τυμπανίζω","o":1,"ar":"<f><o>τυμπανίζω</o></f> <s n=\"1.\"><b>قرع الطبل</b>. </s> <s n=\"2.\"><b>عذّب بالضرب، ضرب حتى الموت</b> (قارن <r v=\"Heb.11.35\"></r>): المبني للمجهول، <r v=\"Heb.11.35\"></r>.†</s>","en":"<f><o>τυμπανίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>τύμπανον</g>, a kettle-drum), </e> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.21.13\"></r> (14) (<h n=\"H????\">תָּוָה</h> pi?) * ;] </e> </et> <s n=\"1.\"><b>to beat a drum</b>. </s> <s n=\"2.\"><b>to torture by beating, beat to death</b> (cf. Westc. on <r v=\"Heb.11.35\"></r>): pass., <r v=\"Heb.11.35\"></r>.†</s>"},"G5171":{"l":"τρυφάω","o":1,"ar":"<f><o>τρυφάω</o>، <g>-ῶ</g></f> <s><b>تنعّم، عاش في ترف، تمتّع بالرفاهية</b>: <r v=\"Jas.5.5\"></r> (قارن <g>ἐν-τρυφάω</g>).†</s>","en":"<f><o>τρυφάω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>τρυφή</g>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Neh.9.25\"></r> (<h n=\"H5727\">עָדַן</h> hithp.), <r v=\"Isa.66.11\"></r> (<h n=\"H6026\">עָנַג</h> hithp.), <r v=\"Sir.14.4\"></r> * ;]</e> </et> <s><b>to live daintily, luxuriously, to fare sumptuously</b>: <r v=\"Jas.5.5\"></r> (cf. <g>ἐν-τρυφάω</g>).†</s> <sy><i>SYN.</i>: <g>σπαταλάω</g> (q.v.), <g>στρηνιάω</g> </sy>"},"G5146":{"l":"τρίβολος","o":2,"ar":"<f><o>τρίβολος</o>، <g>-ου, ὁ </g></f> <s><b>حَسَك (شوك)</b>: <r v=\"Matt.7.16\"></r>، <r v=\"Heb.6.8\"></r>.†</s>","en":"<f><o>τρίβολος</o>, <g>-ου, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Gen.3.18\"></r>, <r v=\"Hos.10.8\"></r> (<h n=\"H1863\">דַּרְדַּר</h>), <r v=\"2Sam.12.31\"></r> (<h n=\"H2757\">חָרִיץ</h>), <r v=\"Prov.22.5\"></r> (<h n=\"H6791\">צֵן</h>)* ;] </e> </et> <s><b>a thistle</b>: <r v=\"Matt.7.16\"></r>, <r v=\"Heb.6.8\"></r>.†</s>"},"G5115":{"l":"τόξον","o":1,"ar":"<f><o>τόξον</o>، <g>-ου, τό </g></f> <s><b>قوس</b>: <r v=\"Rev.6.2\"></r>.†</s>","en":"<f><o>τόξον</o>, <g>-ου, τό </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7198\">קֶשֶׁת</h> ;] </e> </et> <s><b>a bow</b>: <r v=\"Rev.6.2\"></r>.†</s>"},"G5136":{"l":"τραχηλίζω","o":1,"ar":"<f>† <o>τραχηλίζω</o></f> <s>أصلاً، عن المصارعين، </s> <s><b>أمسك بالعنق</b>، ومن ثَمّ <b>صرع، طرح أرضًا</b>. مجازيًا، لكن المعنى المقصود وعصر هذا الاستعمال غير مؤكَّدين (قارن <r v=\"Heb.4.13\"></r>)، <g>τραχηλισμένα</g>، <b>مكشوف، عريان</b> (أو <b>مُطأطئ الرأس</b>): <r v=\"Heb.4.13\"></r>.†</s>","en":"<f>† <o>τραχηλίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>τράχηλος</g>), </e> </et> <s>prop., of wrestlers, </s> <s><b>to take by the throat</b>, hence (Philo), <b>to prostrate, overthrow</b>. Metaph., but in what sense and from what age it is doubtful (v. Westc., Rendall, on <r v=\"Heb.4.13\"></r>; <i>DB</i>, iii, 625n), <g>τραχηλισμένα</g>, <b>laid open</b> (RV, Westc.; <b>downcast</b>, Rendall): <r v=\"Heb.4.13\"></r>.†</s>"},"G5192":{"l":"ὑακίνθος","o":1,"ar":"<f><o>ὑακίνθος</o>، <g>-ου, ό </g></f> <s><b>أسمانجوني (ياقوت أزرق)</b>؛ </s> <s n=\"(a)\">في اليونانية الكلاسيكية: زهرة، ربما السوسن الأزرق الداكن؛ </s> <s n=\"(b)\">عند الكتّاب المتأخرين، حجر كريم من اللون نفسه، ربما الياقوت الأزرق (السفير): <r v=\"Rev.21.20\"></r>.†</s>","en":"<f><o>ὑακίνθος</o>, <g>-ου, ό </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8504\">תְּכֵלֶת</h> ;] </e> </et> <s><b>hyacinth</b>; </s> <s n=\"(a)\">in cl., a flower, prob. the dark blue iris; </s> <s n=\"(b)\">in late writers, a precious stone of the same colour, perhaps the sapphire: <r v=\"Rev.21.20\"></r> (Phil., FlJ, al.).†</s>"},"G5131":{"l":"τράγος","o":4,"ar":"<f><o>τράγος</o>، <g>-ου, ὁ </g></f> <s><b>تيس</b>: <r v=\"Heb.9.12\"></r>، <r v=\"Heb.9.13\"></r>، <r v=\"Heb.9.19\"></r>، <r v=\"Heb.10.4\"></r>.†</s>","en":"<f><o>τράγος</o>, <g>-ου, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6260\">עַתּוּד</h>, also for <h n=\"H6842\">צָפִיר</h>, <h n=\"H8495\">תַּיִשׁ</h> ;]</e> </et> <s>a <b>he-goat</b>: <r v=\"Heb.9.12\"></r>, <r v=\"Heb.9.13\"></r>, <r v=\"Heb.9.19\"></r> <r v=\"Heb.10.4\"></r>.†</s>"},"G5114":{"l":"τομός","o":1,"ar":"<f>* <o>τομός</o>، <g>-ή, -όν</g></f> <s><b>قاطع، حادّ</b>: صيغة التفضيل، <g>-ώτερος</g>، مجازيًا، <r v=\"Heb.4.12\"></r>.†</s>","en":"<f>* <o>τομός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>τέμνω</g>), </e> </et> <s><b>sharp</b>: compar., <g>-ώτερος</g>, metaph., <r v=\"Heb.4.12\"></r>.†</s>"},"G5150":{"l":"τρίμηνος","o":1,"ar":"<f><o>τρίμηνος</o>، <g>-ον</g></f> <s><b>ذو ثلاثة أشهر</b>؛ اسمًا، <g>τὸ τ.</g> (وفي الكلاسيكية <g>ἡ τ.</g>)، <b>مدة ثلاثة أشهر</b>: <r v=\"Heb.11.23\"></r>.† </s>","en":"<f><o>τρίμηνος</o>, <g>-ον</g></f> <et> <e t=\"derivation\">(&lt; <g>τρεῖς</g>, <g>μήν</g>) </e> <e t=\"septuagint\">[in LXX (neut.): <r v=\"Gen.38.24\"></r>, <r v=\"2Kgs.23.31\"></r> B <r v=\"2Kgs.24.8\"></r>, <r v=\"2Chr.36.2\"></r>, <r v=\"2Chr.36.9\"></r> (<h n=\"H2320\">חֳדָשִׁים</h> <h n=\"H7969\"> שָׁלוֹשׁ</h>) * ;] </e> </et> <s><b>of three months</b>; as subst., <g>τὸ τ.</g> (= cl. <g>ἡ τ.</g>), <b>a space of three months</b> (Polyb., al.; LXX): <r v=\"Heb.11.23\"></r>.† </s>"},"G5193":{"l":"ὑάλινος","o":3,"ar":"<f>* <o>ὑάλινος</o>، <g>-η, -ον</g></f> <s><b>زجاجي، شبه الزجاج</b> <r v=\"Rev.4.6\"></r> <r v=\"Rev.15.2\"></r>.†</s>","en":"<f>* <o>ὑάλινος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>ὕαλος</g>), </e> </et> <s><b>of glass, glassy</b> <r v=\"Rev.4.6\"></r> <r v=\"Rev.15.2\"></r>.†</s>"},"G5164":{"l":"τροχός","o":1,"ar":"<f><o>τροχός</o>، <g>-οῦ, τό</g></f> <s><b>دولاب، عجلة</b>: <r v=\"Jas.3.6\"></r>.†</s>","en":"<f><o>τροχός</o>, <g>-οῦ, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>τρέχω</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H212\">אוֹפָן</h> ;] </e> </et> <s><b>a wheel</b>: <r v=\"Jas.3.6\"></r> (v. Mayor, Hort, in l.).†</s>"},"G5184":{"l":"Τύρος","o":11,"ar":"<f><o>Τύρος</o>، <g>-ου, ἡ </g></f> <s><b>صور</b>، مدينة ساحلية في فينيقية: <r v=\"Mark.7.31\"></r>، <r v=\"Acts.21.3\"></r>، <r v=\"Acts.21.7\"></r>؛ <g>Τ. κ, Σιδών</g>، <r v=\"Matt.11.21\"></r>، <r v=\"Matt.11.22\"></r> <r v=\"Matt.15.21\"></r>، <r v=\"Mark.3.8\"></r> <r v=\"Mark.7.24\"></r>، <r v=\"Luke.6.17\"></r> <r v=\"Luke.10.13\"></r>، <r v=\"Luke.10.14\"></r>.†</s>","en":"<f><o>Τύρος</o>, <g>-ου, ἡ </g></f> <s><b>Tyre</b>, a maritime city of Phænicia: <r v=\"Mark.7.31\"></r>, <r v=\"Acts.21.3\"></r>, <r v=\"Acts.21.7\"></r>; <g>Τ. κ, Σιδών</g>, <r v=\"Matt.11.21\"></r>, <r v=\"Matt.11.22\"></r> <r v=\"Matt.15.21\"></r>, <r v=\"Mark.3.8\"></r> <r v=\"Mark.7.24\"></r>, <r v=\"Luke.6.17\"></r> <r v=\"Luke.10.13\"></r>, <r v=\"Luke.10.14\"></r>.†</s>"},"G5102":{"l":"τίτλος","o":2,"ar":"<f>**† <o>τίτλος</o>، <g>-ου, ὁ </g></f> <s><b>عنوان، كتابة</b>: <r v=\"John.19.19\"></r>، <r v=\"John.19.20\"></r>.†</s>","en":"<f>**† <o>τίτλος</o>, <g>-ου, ὁ </g></f> <et> <e t=\"derivation\">(Lat. <l>titulus</l>), </e> <e t=\"septuagint\">[in Aq., Sm., Th.: <r v=\"Jer.21.4\"></r> * ;] </e> </et> <s><b>a title, inscription</b>: <r v=\"John.19.19\"></r>, <r v=\"John.19.20\"></r> (in Christian Inscr., <b>epitaph</b>, v. MM. xxiv).†</s>"},"G5133":{"l":"τραπεζείτης","o":1,"ar":"<f>* <o>τραπεζείτης</o>، <g>-ου, ὁ</g> </f> <s><b>صرّاف، صيرفي</b>: <r v=\"Matt.25.27\"></r>.†</s>","en":"<f>* <o>τραπεζείτης</o> (Rec. <g>-ζίτης</g>, as in cl.), <g>-ου, ὁ</g> </f> <et> <e t=\"derivation\">(&lt; <g>τράπεζα</g>), </e> </et> <s><b>a money­changer, banker</b>: <r v=\"Matt.25.27\"></r> (Dem., Plut., al.).†</s>"},"G5168":{"l":"τρυμαλιά","o":1,"ar":"<f>† <o>τρυμαλιά</o>، <g>-ᾶς, ἡ</g></f> <s>= <g>τρύμη</g>، <b>ثقب</b>: <g>τ. ῥαφίδος</g>، <b>ثقب الإبرة</b>، <r v=\"Mark.10.25\"></r>.†</s>","en":"<f>† <o>τρυμαλιά</o>, <g>-ᾶς, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>τρύω</g>, <b>to wear away</b>), </e> <e t=\"septuagint\">[in LXX: <r v=\"Jer.13.4\"></r> (<h n=\"H5357\">נָקִיק</h>), etc. ;] </e> </et> <s>= <g>τρύμη</g>, <b>a hole</b>: <g>τ. ῥαφίδος</g>, <b>eye of a needle</b>, <r v=\"Mark.10.25\"></r>.†</s> <sy><i>SYN.</i>: <g>τρῆμα</g>, <g>τρύπημα</g> </sy>"},"G5109":{"l":"τοῖχος","o":1,"ar":"<f><o>τοῖχος</o>، <g>-ου, ὁ </g></f> <s><b>حائط</b>، خاصةً حائط البيت: مجازيًا، <r v=\"Acts.23.3\"></r> (قارن <g>τεῖχος</g>).†</s>","en":"<f><o>τοῖχος</o>, <g>-ου, ὁ </g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7023\">קִיר</h> ;] </e> </et> <s><b>a wall</b>, esp. of a house: fig., <r v=\"Acts.23.3\"></r> (cf. <g>τεῖχος</g>).†</s>"},"G5148":{"l":"τριετία","o":1,"ar":"<f>* <o>τριετία</o>، <g>-ας, ἡ</g></f> <s><b>مدة ثلاث سنين</b>: <r v=\"Acts.20.31\"></r>.†</s>","en":"<f>* <o>τριετία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>τρεῖς</g>, <g>ἔτος</g>), </e> </et> <s><b>a period of three years</b>: <r v=\"Acts.20.31\"></r>.†</s>"},"G5153":{"l":"τρισχίλιοι","o":1,"ar":"<f><o>τρισ-χίλιοι</o>، <g>-αι, -α </g></f> <s><b>ثلاثة آلاف</b>: <r v=\"Acts.2.41\"></r>.†</s>","en":"<f><o>τρισ-χίλιοι</o>, <g>-αι, -α </g></f> <s><b>three thousand</b>: <r v=\"Acts.2.41\"></r>.†</s>"},"G5183":{"l":"Τύριος","o":1,"ar":"<f><o>Τύριος</o>، <g>-ου, ὁ, ἡ </g></f> <s><b>صوري</b>: <r v=\"Acts.12.20\"></r>.†</s>","en":"<f><o>Τύριος</o>, <g>-ου, ὁ, ἡ </g></f> <s><b>a Tyrian</b>: <r v=\"Acts.12.20\"></r>.†</s>"},"G5149":{"l":"τρίζω","o":1,"ar":"<f>** <o>τρίζω </o></f> <s n=\"1.\">أصلاً: عن أصوات الحيوانات، <b>صاح، صرّ</b>، إلخ. </s> <s n=\"2.\">عن أصوات أخرى، مثلاً متعديًا: <g>τ. ὀδόντας</g>: <b>صرّ</b> أو <b>صرف بأسنانه</b>: <r v=\"Mark.9.18\"></r>.†</s>","en":"<f>** <o>τρίζω </o></f> <et> <e t=\"septuagint\">[in Aq.: <r v=\"Amos.2.13\"></r>; Sm.: <r v=\"Isa.38.14\"></r> * ;] </e> </et> <s n=\"1.\">prop., of sounds by animals, <b>to cry, chirp</b>, etc. </s> <s n=\"2.\">Of other sounds, e.g., trans., <g>τ. ὀδόντας</g>, <b>to gnash</b> or <b>grind the teeth</b>: <r v=\"Mark.9.18\"></r>.†</s>"},"G5138":{"l":"τραχύς","o":2,"ar":"<f><o>τραχύς</o>، <g>-εῖα, -ύ </g></f> <s><b>وعر، خشن</b>: <g>ὁδοί</g> (<r v=\"Isa.40.4\"></r>)، <r v=\"Luke.3.5\"></r>؛ <g>τοποί</g> (أي صخرية)، <r v=\"Acts.27.29\"></r>.†</s>","en":"<f><o>τραχύς</o>, <g>-εῖα, -ύ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.40.4\"></r> (<h n=\"H7406\">רֶכֶס</h>), etc. ;]</e> </et> <s><b>rough</b>: <g>ὁδοί</g> (<r v=\"Isa.40.4\"></r>), <r v=\"Luke.3.5\"></r> <i>(LXX)</i>; <g>τοποί</g> (i.e. rocky), <r v=\"Acts.27.29\"></r>.†</s>"},"G5165":{"l":"τρύβλιον","o":2,"ar":"<f><o>τρύβλιον</o>، -ου, τό </f> <s><b>صحفة، طبق</b>: <r v=\"Matt.26.23\"></r>، <r v=\"Mark.14.20\"></r>.†</s>","en":"<f><o>τρύβλιον</o> (Rec. <g>τρυβλίον</g>), -ου, τό </f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7086\">קְעָרָה</h> ;] </e> </et> <s><b>a bowl, dish</b>: <r v=\"Matt.26.23\"></r>, <r v=\"Mark.14.20\"></r> (Hippocr., Aristoph., Plut., al.).†</s>"},"G5169":{"l":"τρύπημα","o":1,"ar":"<f>* <o>τρύπημα</o>، <g>-τος, τό</g></f> <s><b>ثقب</b>: <g>τ. ῥαφιδος</g>: <b>ثقب الإبرة</b>، <r v=\"Matt.19.24\"></r>.†</s>","en":"<f>* <o>τρύπημα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>τρυπάω</g>, <b>to bore</b>) </e> </et> <s><b>a hole</b>: <g>τ. ῥαφιδος</g>, <b>eye of a needle</b>, <r v=\"Matt.19.24\"></r> (WH, txt., <g>τρῆμα</g>).†</s> <sy><i>SYN.</i>: <g>τρῆμα</g>, <g>τρυμαλιά</g> </sy>"},"G5188":{"l":"τύφω","o":1,"ar":"<f>* <o>τύφω</o></f> <s><b>أثار دخانًا</b>؛ وفي المبني للمجهول: <b>دخّن</b>: <r v=\"Matt.12.20\"></r> (في السبعينية <g>καπνιζόμενον</g>).†</s>","en":"<f>* <o>τύφω</o></f> <et> <e t=\"derivation\">(&lt; <g>τῦφος</g>, <b>smoke</b> </e> </et> <s><b>to raise a smoke</b>; pass., <b>to smoke</b>: <r v=\"Matt.12.20\"></r> (LXX, <g>καπνιζόμενον</g>).†</s>"},"G5135":{"l":"τραυματίζω","o":2,"ar":"<f><o>τραυματίζω</o></f> <s><b>جرح</b>: <r v=\"Luke.20.12\"></r>، <r v=\"Acts.19.16\"></r>.†</s>","en":"<f><o>τραυματίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>τραῦμα</g>), </e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2490\">חָלַל</h> ;] </e> </et> <s><b>to wound</b>: <r v=\"Luke.20.12\"></r>, <r v=\"Acts.19.16\"></r>.†</s>"},"G5139":{"l":"Τραχωνῖτις","o":1,"ar":"<f><o>Τραχωνῖτις</o>، <g>-ιδος, ἡ</g></f> <s><b>تراخونيتس</b>، منطقة وعرة جنوب دمشق: <g>ἡ Τ. χώρα</g>، <r v=\"Luke.3.1\"></r>.†</s>","en":"<f><o>Τραχωνῖτις</o>, <g>-ιδος, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>τραχύς</g>) </e> </et> <s><b>Trachonitis</b>, a rough region S. of Damascus (in FlJ, sometimes <g>ἡ Τ.</g>, sometimes <g>ό Τράχων</g>): <g>ἡ Τ. χώρα</g>, <r v=\"Luke.3.1\"></r>.†</s>"},"G5152":{"l":"τρίστεγος","o":1,"ar":"<f>**† <o>τρίστεγος</o>، <g>-ον (τρεῖς, στέγη) </g></f> <s><b>ذو ثلاث طبقات</b>: <g>τὸ τ.</g> (والمقدَّر <g>ὄκημα</g>)، </s> <s><b>الطبقة الثالثة</b>، <r v=\"Acts.20.9\"></r>.†</s>","en":"<f>**† <o>τρίστεγος</o>, <g>-ον (τρεῖς, στέγη) </g></f> <et> <e t=\"septuagint\">[in Sm.: <r v=\"Gen.6.17\"></r>(16), <r v=\"Ezek.42.6\"></r> * ;] </e> </et> <s><b>of three stories</b>: <g>τὸ τ.</g> (sc. <g>ὄκημα</g>), </s> <s><b>the third story</b>, <r v=\"Acts.20.9\"></r> (Dion., FlJ, al.).†</s>"},"G5145":{"l":"τριακόσιοι","o":2,"ar":"<f><o>τριακόσιοι</o>، <g>-αι, -α </g></f> <s><b>ثلاث مئة</b>: <r v=\"Mark.14.5\"></r>، <r v=\"John.12.5\"></r>.†</s>","en":"<f><o>τριακόσιοι</o>, <g>-αι, -α </g></f> <s><b>three hundred</b>: <r v=\"Mark.14.5\"></r>, <r v=\"John.12.5\"></r>.†</s>"},"G5181":{"l":"Τύραννος","o":1,"ar":"<f><o>Τύραννος</o>، <g>-ου, ὀ </g></f> <s><b>تيرانس</b>: <r v=\"Acts.19.9\"></r>.†</s>","en":"<f><o>Τύραννος</o>, <g>-ου, ὀ </g></f> <s><b>Tyrannus</b>: <r v=\"Acts.19.9\"></r>.†</s>"},"G5122":{"l":"τοὔνομα","o":1,"ar":"<f><o>τοὔνομα </o></f> <s>بالدمج عن <g>τὸ ὄνομα</g>، منصوب مطلق، </s> <s><b>اسمه، باسم</b>: <r v=\"Matt.27.57\"></r>.†</s>","en":"<f><o>τοὔνομα </o></f> <s>by crasis for <g>τὸ ὄνομα</g>, acc absol., </s> <s><b>by name</b>: <r v=\"Matt.27.57\"></r>.†</s>"},"G5134":{"l":"τραῦμα","o":1,"ar":"<f><o>τραῦμα</o>، <g>-τος, τό </g></f> <s><b>جرح</b>: <r v=\"Luke.10.34\"></r>.†</s>","en":"<f><o>τραῦμα</o>, <g>-τος, τό </g></f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6481\">פָּצַע</h>, <h n=\"H2490\">חָלַל</h>, etc. ;]</e> </et> <s><b>a wound</b>: <r v=\"Luke.10.34\"></r>.†</s>"},"G5110":{"l":"τόκος","o":2,"ar":"<f><o>τόκος</o>، <g>-ου, ὁ</g></f> <s n=\"(a)\"><b>ولادة، إنجاب</b>؛ </s> <s n=\"(b)\"><b>نسل، مولود</b>. مجازيًا، عن ريع المال المُقرَض، <b>ربا، فائدة</b>: <r v=\"Matt.25.27\"></r>، <r v=\"Luke.19.23\"></r>.†</s>","en":"<f><o>τόκος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>τίκτω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H5392\">נֶשֶׁךְ</h>, etc. ;]</e> </et> <s n=\"(a)\"><b>a bringing forth, birth</b>; </s> <s n=\"(b)\"><b>offspring</b>. Metaph., of the produce of money lent out, <b>interest, usury</b> (cf. <i>Merch. of Venice</i>, I, iii, \"a breed of barren metal \"): <r v=\"Matt.25.27\"></r>, <r v=\"Luke.19.23\"></r> (Soph., Plat., al.).†</s>"},"G5189":{"l":"τυφωνικός","o":1,"ar":"<f>*† <o>τυφωνικός</o>، <g>-ή, -όν</g></f> <s><b>عاصف، زوبعيّ</b>: <r v=\"Acts.27.14\"></r>.†</s>","en":"<f>*† <o>τυφωνικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>τῦφων</g>, <b>a hurricane, typhoon</b>) </e> </et> <s><b>tempestuous</b>: <r v=\"Acts.27.14\"></r>.†</s>"},"G5176":{"l":"τρώγω","o":6,"ar":"<f>* <o>τρώγω </o></f> <s n=\"1.\">في اليونانية الكلاسيكية: أصلاً، عن الحيوانات، <b>قضم، مضغ، قرض</b>. </s> <s n=\"2.\">في اليونانية الكلاسيكية: عن البشر، <b>أكل</b> الطعام النيئ، كالخضروات والجوز إلخ. </s> <s n=\"3.\">في اللغة الدارجة المتأخرة، ببساطة <b>أكل</b> (= <g>ἐσθίω</g>): <r v=\"Matt.24.38\"></r>، <r v=\"John.6.54\"></r>، <r v=\"John.6.56\"></r>، <r v=\"John.6.57\"></r>، <r v=\"John.6.58\"></r> <r v=\"John.13.18\"></r> (السبعينية <g>ἐσθίων</g>).†</s>","en":"<f>* <o>τρώγω </o></f> <s n=\"1.\">prop., of animals, <b>to gnaw, munch, crunch</b> (Hom., al.). </s> <s n=\"2.\">Of men, <b>to eat</b> raw food, as vegetables, nuts, etc. (Hdt., al.). </s> <s n=\"3.\">In late vernacular, simply <b>to eat</b> (= <g>ἐσθίω</g>): <r v=\"Matt.24.38\"></r>, <r v=\"John.6.54\"></r>, <r v=\"John.6.56\"></r>, <r v=\"John.6.57\"></r>, <r v=\"John.6.58\"></r> <r v=\"John.13.18\"></r> (LXX <g>ἐσθίων</g>) (v. Kennedy, <i>Sources</i>, 82, 155; MM, xxv).†</s>"},"G5159":{"l":"τροποφορέω","o":1,"ar":"<f>† <o>τροπο-φορέω</o>، <g>-ῶ </g></f> <s n=\"1.\"><b>احتمل عوائد غيره</b>: مع منصوب الشخص، <r v=\"Acts.13.18\"></r>. </s> <s n=\"2.\">= <g>τροφοφορέω</g> (انظره): <r v=\"Acts.13.18\"></r>†</s>","en":"<f>† <o>τροπο-φορέω</o>, <g>-ῶ </g></f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Deut.1.31\"></r> B.l (<h n=\"H5375\">נָשָׂא</h>) * ;] </e> </et> <s n=\"1.\"><b>to bear another's manners</b> (R, txt., <i>suffered he their manners</i>): c. acc pers., <r v=\"Acts.13.18\"></r> (Rec., WH, R, txt.; <g>ἐτροφο-</g>, T, R, mg.). </s> <s n=\"2.\">= <g>τροφοφορέω</g> (q.v.), (v. Kühner<i>3</i>, I, 276): <r v=\"Acts.13.18\"></r>†</s>"},"G5147":{"l":"τρίβος","o":3,"ar":"<f><o>τρίβος</o>، <g>-ου, -ἡ</g></f> <s><b>طريق مطروق، سبيل</b>: <r v=\"Matt.3.3\"></r>، <r v=\"Mark.1.3\"></r>، <r v=\"Luke.3.4\"></r> <i>(السبعينية)</i>.†</s>","en":"<f><o>τρίβος</o>, <g>-ου, -ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>τρίβω</g>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H4546\">מְסִלָּה</h>, <h n=\"H5410\">נָתִיב</h>, etc. ;]</e> </et> <s><b>a beaten track, a path</b>: <r v=\"Matt.3.3\"></r>, <r v=\"Mark.1.3\"></r>, <r v=\"Luke.3.4\"></r> <i>(LXX)</i>.†</s>"},"G5167":{"l":"τρυγών","o":1,"ar":"<f><o>τρυγών</o>، <g>-όνος, ἡ</g></f> <s><b>يمامة</b>: <r v=\"Luke.2.24\"></r>.†</s>","en":"<f><o>τρυγών</o>, <g>-όνος, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>τρύζω</g>, <b>to murmur, coo</b>), </e> <e t=\"septuagint\">[in LXX for <h n=\"H8447\">תּוֹר</h>, <h n=\"H8447\">תֹּר</h>;]</e> </et> <s><b>a turtle-dove</b>: <r v=\"Luke.2.24\"></r>.†</s>"}});A.got[51]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});